--
-- Name: vi_bs_item_guard(); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_bs_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.category IS NULL OR NEW.category NOT IN ('经营资产', '经营负债', '现金与投资', '参照估值', '有息负债', '其他索取权') THEN
    RAISE EXCEPTION '请填写有效的类别';
  END IF;
  IF NEW.haircut IS NOT NULL AND (NEW.haircut < 0 OR NEW.haircut > 1) THEN RAISE EXCEPTION '折价必须在 0 到 1 之间'; END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.vi_bs_item_guard() OWNER TO nocobase;

