--
-- Name: vi_collect_targets(bigint); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_collect_targets(p_run bigint) RETURNS TABLE(id bigint, name text, url text)
    LANGUAGE sql STABLE
    AS $$
SELECT k.id, k.name, k.url
FROM vi_collector_base k
JOIN vi_metric_base m ON m.id = k.metric_id
LEFT JOIN vi_collect_run_base r ON r.id = p_run
WHERE k.enabled
  AND (r.company_id IS NULL
       OR EXISTS (SELECT 1 FROM vi_company_metric cm WHERE cm.company_id = r.company_id AND cm.metric_id = m.id))
ORDER BY k.id
$$;


ALTER FUNCTION public.vi_collect_targets(p_run bigint) OWNER TO nocobase;

