  END IF;
END $$;


ALTER FUNCTION public.vi_growth_dml() OWNER TO nocobase;

--
-- Name: vi_gw_equity(double precision[], double precision[], double precision[], integer[], integer[], boolean, double precision, double precision); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_gw_equity(e double precision[], g double precision[], ro double precision[], n integer[], life integer[], with_growth boolean, konst double precision, r double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT sum(vi_gw_pv(ee, CASE WHEN with_growth THEN gg ELSE 0 END, rr, nn, ll, r)) + konst
  FROM unnest(e, g, ro, n, life) AS x(ee, gg, rr, nn, ll)
$$;


ALTER FUNCTION public.vi_gw_equity(e double precision[], g double precision[], ro double precision[], n integer[], life integer[], with_growth boolean, konst double precision, r double precision) OWNER TO nocobase;

--
-- Name: vi_gw_irr(double precision[], double precision[], double precision[], integer[], integer[], boolean, double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_gw_irr(e double precision[], g double precision[], ro double precision[], n integer[], life integer[], with_growth boolean, konst double precision, shares double precision, elapsed double precision, price double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE lo double precision; hi double precision := 1.0; mid double precision; i int;
BEGIN
  IF price IS NULL OR price <= 0 OR shares IS NULL OR shares <= 0 OR konst IS NULL OR e IS NULL THEN RETURN NULL; END IF;
  lo := 1e-4 + CASE WHEN with_growth THEN greatest(0, coalesce((SELECT max(gg) FROM unnest(g, n, life) AS x(gg, nn, ll)
                                                                 WHERE nn IS NULL AND ll IS NULL), 0)) ELSE 0 END;
  IF vi_gw_equity(e, g, ro, n, life, with_growth, konst, lo) * power(1 + lo, elapsed) / shares < price THEN RETURN NULL; END IF;
  IF vi_gw_equity(e, g, ro, n, life, with_growth, konst, hi) * power(1 + hi, elapsed) / shares > price THEN RETURN NULL; END IF;
  FOR i IN 1..60 LOOP
    mid := (lo + hi) / 2;
    IF vi_gw_equity(e, g, ro, n, life, with_growth, konst, mid) * power(1 + mid, elapsed) / shares > price THEN lo := mid; ELSE hi := mid; END IF;
  END LOOP;
  RETURN (lo + hi) / 2;
END $$;


ALTER FUNCTION public.vi_gw_irr(e double precision[], g double precision[], ro double precision[], n integer[], life integer[], with_growth boolean, konst double precision, shares double precision, elapsed double precision, price double precision) OWNER TO nocobase;

--
-- Name: vi_gw_pv(double precision, double precision, double precision, integer, integer, double precision); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_gw_pv(e double precision, g double precision, ronic double precision, n integer, life integer, r double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE gg double precision := coalesce(g, 0); k integer; q double precision; pv double precision;
BEGIN
  IF e IS NULL OR r IS NULL OR r <= 0 THEN RETURN NULL; END IF;
  IF life IS NOT NULL AND life <= 0 THEN RETURN 0; END IF;
  IF gg = 0 THEN
    RETURN CASE WHEN life IS NULL THEN e / r ELSE e * (1 - power(1 + r, -life)) / r END;
  END IF;
  IF ronic IS NULL OR ronic <= 0 THEN RETURN NULL; END IF;
  IF n IS NULL AND life IS NULL THEN                        -- 永续增长
    IF gg >= r THEN RETURN NULL; END IF;
    RETURN e * (1 - gg / ronic) / (r - gg);
  END IF;
  k := CASE WHEN n IS NULL THEN life WHEN life IS NULL THEN n ELSE least(n, life) END;
  q := (1 + gg) / (1 + r);
  -- 优势期：第 t 年收益 e(1+g)^(t−1)，再投入 g÷ronic 后的现金流折现
  pv := e * (1 - gg / ronic) / (1 + r) * CASE WHEN abs(q - 1) < 1e-12 THEN k ELSE (1 - power(q, k)) / (1 - q) END;
  -- 优势期后：收益停在 e(1+g)^k，永续或到盈利年限
  RETURN pv + e * power(1 + gg, k) / power(1 + r, k)
              * CASE WHEN life IS NULL THEN 1 / r ELSE (1 - power(1 + r, -(life - k))) / r END;
END $$;


ALTER FUNCTION public.vi_gw_pv(e double precision, g double precision, ronic double precision, n integer, life integer, r double precision) OWNER TO nocobase;

