    LANGUAGE plpgsql
    AS $$
DECLARE mid bigint;
BEGIN
  SELECT id INTO mid FROM vi_metric_base WHERE company_id = p_company AND name = p_name AND unit IS NOT DISTINCT FROM p_unit ORDER BY id LIMIT 1;
