--
-- Name: TABLE vi_biz_model_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_biz_model_base IS '商业模式拆解：用商业模式画布 9 项讲清公司怎么赚钱；引用【定性事实】【业务分部】【指标】。商业模式画布 9 项，每块业务一项一行（B1—B9 按画布顺序）；所属业务留空表示集团整体或共性，不表示自动继承。投资者关心的内容放进画布：盈利公式的收入一侧、收入结构、单价、增长与周期写在“收入来源”；盈利公式的成本一侧、成本构成、单位利润、资本需求与现金循环写在“成本结构”。只写事实与机制；有争议、决定价值的判断写在核心论点里。';


--
-- Name: COLUMN vi_biz_model_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_biz_model_base.code IS '编号：B1—B9，按画布顺序；在公司和所属业务内唯一';


--
-- Name: COLUMN vi_biz_model_base.element; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_biz_model_base.element IS '要素：客户细分：卖给谁｜价值主张：为什么买｜渠道通路：怎么触达和交付｜客户关系：怎么留住、合同与结算方式｜收入来源：收入公式（量×价）、结构、单价、增长与周期｜核心资源：不可或缺的资产与能力｜关键业务：公司自己做的事｜重要合作：控股股东、供应商、伙伴｜成本结构：成本构成、经营杠杆、单位利润、资本需求与现金循环（可选：客户细分、价值主张、渠道通路、客户关系、收入来源、核心资源、关键业务、重要合作、成本结构）';


--
-- Name: COLUMN vi_biz_model_base.title; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_biz_model_base.title IS '要点';


--
-- Name: COLUMN vi_biz_model_base.content; Type: COMMENT; Schema: public; Owner: nocobase
