--
-- Name: TABLE vi_bs_item_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_bs_item_base IS '资产负债重估：资产负债表逐科目归类与重估：每个科目要么是某块业务的经营资本，要么进资产负债桥；引用【业务分部】【假设依据】【财务报表】【估值模型】；被【三层价值·业务】【三层价值·结果】【三层估值检查】引用。一行一个资产负债表科目（取估值模型截至日的报表），或一项报表外的研究调整。挂了业务＝这块业务的经营资本（第一层资产价值、ROIC 的分母）；没挂业务＝资产负债桥（现金与投资、有息负债、其他索取权），把经营价值换成股权价值。重估金额＝账面×(1−折价)＋调整额；计入值按类别带正负号：经营资产、现金与投资为正，经营负债、有息负债、其他索取权为负。全部行的账面计入值合计必须等于报表的归母股东权益（检查 G01），这样每个科目只计一次、不漏不重。口径开关：企业口径的业务不挂有息负债（债务在桥里扣）；股权口径的业务（银行、保险、地产开发等）把有息负债挂在业务上，利润用利息后口径。';


--
-- Name: COLUMN vi_bs_item_base.category; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.category IS '类别：经营资产、现金与投资计正；经营负债、有息负债、其他索取权（少数股东、预提税、或有义务等）计负（可选：经营资产、经营负债、现金与投资、有息负债、其他索取权）';


--
-- Name: COLUMN vi_bs_item_base.line_item; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.line_item IS '报表科目：与「财务报表」资产负债表的科目名完全一致；留空＝报表外的研究项目（如经营所需现金的划转、汇出预提税）';


--
-- Name: COLUMN vi_bs_item_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.name IS '项目：显示名称；留空＝报表科目';


--
-- Name: COLUMN vi_bs_item_base.haircut; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.haircut IS '折价：对账面打的折扣：对外投资的持有折价与处置税费；商誉不计入资产价值填 100%（小数，0.05＝5%）';


--
-- Name: COLUMN vi_bs_item_base.adjustment; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.adjustment IS '调整额（亿元）：在“账面×(1−折价)”之上加减的研究调整，与本行方向一致（负债行填正数＝负债更多）；研究项目的金额填这里';


--
-- Name: COLUMN vi_bs_item_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.basis IS '依据：为什么这样归类、调整；金额推导写清';


--
-- Name: COLUMN vi_bs_item_base.sort; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_bs_item_base.sort IS '排序';


