--
-- Name: vi_bs_item_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_bs_item_calc AS
 WITH x AS (
         SELECT b.id,
            co.as_of,
            b.category,
            b.haircut,
            b.adjustment,
                CASE
                    WHEN (NULLIF(btrim(b.line_item), ''::text) IS NULL) THEN (0)::double precision
                    ELSE ( SELECT f.amount
                       FROM public.vi_fin_stmt_base f
                      WHERE ((f.company_id = b.company_id) AND (f.stmt = '资产负债表'::text) AND (f.period_end = co.as_of) AND (f.item = btrim(b.line_item))))
                END AS book,
                CASE
                    WHEN (b.category = ANY (ARRAY['经营资产'::text, '现金与投资'::text, '参照估值'::text])) THEN 1
                    WHEN (b.category = ANY (ARRAY['经营负债'::text, '有息负债'::text, '其他索取权'::text])) THEN '-1'::integer
                    ELSE NULL::integer
                END AS sgn
           FROM (public.vi_bs_item_base b
             LEFT JOIN public.vi_company_base co ON ((co.id = b.company_id)))
        ), y AS (
         SELECT x.id,
            x.as_of,
            x.category,
            x.haircut,
            x.adjustment,
            x.book,
            x.sgn,
            ((x.book * ((1)::double precision - COALESCE(x.haircut, (0)::double precision))) + COALESCE(x.adjustment, (0)::double precision)) AS revalued
           FROM x
        )
 SELECT id,
    as_of,
    book,
    revalued,
    ((sgn)::double precision * book) AS book_signed,
    ((sgn)::double precision * revalued) AS value_signed,
        CASE
            WHEN (category = ANY (ARRAY['经营资产'::text, '经营负债'::text])) THEN '经营资本'::text
            ELSE '资产负债桥'::text
        END AS role
   FROM y;


ALTER VIEW public.vi_bs_item_calc OWNER TO nocobase;

--
-- Name: vi_bs_item; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_bs_item AS
 SELECT b.id,
    b.category,
    b.line_item,
    b.name,
    b.haircut,
    b.adjustment,
    b.basis,
    b.sort,
    b.company_id,
    c.as_of,
    c.book,
    c.revalued,
    c.book_signed,
    c.value_signed,
    c.role,
    b.updated_at
   FROM (public.vi_bs_item_base b
     LEFT JOIN public.vi_bs_item_calc c ON ((c.id = b.id)));


