    valid_max double precision,
    notes text,
    company_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_kind text DEFAULT '自动采集'::text,
    basis text DEFAULT '时点'::text,
    formula text,
    model_field text,
    measure text,
    CONSTRAINT vi_metric_source_required CHECK ((NULLIF(btrim(source_name), ''::text) IS NOT NULL))
);


ALTER TABLE public.vi_metric_base OWNER TO nocobase;

--
-- Name: TABLE vi_metric_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_metric_base IS '指标：一家公司要看的每一个数（经营、财务、行情与环境），一个指标一行：从哪来、最新值、是否到期；被【公司】【商业模式拆解】【产业链与五力】【竞争壁垒】【核心论点】【风险分析】【假设依据】【数据】【估值模型】【资产估值与调整】【经营分部估值】【逐年假设】【采集配置】【历史年度】【指标数值】【质量自检】引用。每期的数在「数据」里，口径记在每期数据上。来源方式：自动采集、公司披露／年报／手工整理（在「数据」里录）、报表计算（按报表公式从三大报表实时算，不另存）。所属公司为空的是宏观数据。';


--
-- Name: COLUMN vi_metric_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.code IS '指标代码：稳定的英文代码，如 600900.SH.PRICE';


--
-- Name: COLUMN vi_metric_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.name IS '指标名称';


--
-- Name: COLUMN vi_metric_base.unit; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.unit IS '单位：利率类直接存百分数值，如 1.65 表示 1.65%';


--
-- Name: COLUMN vi_metric_base.category; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.category IS '类别：业务驱动选经营，收入/利润/现金及分部财务选财务；合同额、合约销售额仍是业务。（可选：行情、利率、汇率、商品、宏观、水文、经营、财务、其他）';


--
-- Name: COLUMN vi_metric_base.source_name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.source_name IS '数据来源';


--
-- Name: COLUMN vi_metric_base.frequency; Type: COMMENT; Schema: public; Owner: nocobase
--

