-- Name: COLUMN vi_metric_base.notes; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.notes IS '说明';


--
-- Name: COLUMN vi_metric_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.company_id IS '所属公司（关联 公司）';


--
-- Name: COLUMN vi_metric_base.source_kind; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.source_kind IS '来源方式：类别区分业务与财务；公司披露/年报/手工整理的业务在“定期经营数据”，自动采集的水文、商品和经营指标在“高频业务数据”。（可选：自动采集、公司披露、年报、手工整理）';


--
-- Name: COLUMN vi_metric_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.basis IS '主口径：最新值、趋势和重点跟踪按这个口径取；每期数据自己的口径记在「数据」上。时点指标只能选“时点”（可选：时点、单季、半年累计、前三季度累计、全年、年初至今累计、滚动四季度）';


--
-- Name: COLUMN vi_metric_base.formula; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.formula IS '报表公式：报表计算的指标填，科目相加减；比率用“÷”，结果为 %';


--
-- Name: COLUMN vi_metric_base.model_field; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.model_field IS '模型字段：这个指标是财务模型历史一侧的哪一列（每家公司每列一个指标）；在「数据底稿 / 定量指标」的“模型字段”列标明（可选：volume、revenue、cost_of_sales、pretax_profit、income_tax、np_parent、minority_profit、da、finance_cost、invest_income、equity_income、cfo、capex、investee_cash_div、net_borrowing、interest_debt、cash、equity_parent、dividend_total、dps）';


--
-- Name: COLUMN vi_metric_base.measure; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.measure IS '指标性质：时期指标（流量）＝一段时间内累计发生的量，如营业收入、利润、现金流、销量、回购金额；由它们算出的比率（毛利率、ARPPU）也是时期指标，同类时期可以相加（四个单季≈全年）。时点指标（存量）＝某一时刻的状态或规模，如现金、负债、净资产、负债率、股价、零售价、用户数；不能跨期相加，按季度平均的用户数也算时点。时点指标每期的口径只能是“时点”，时期指标不能用“时点”。留空＝还没判定（可选：时期、时点）';


--
-- Name: vi_observation_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_observation_base (
