    value double precision,
    collected_at timestamp with time zone,
    metric_id bigint,
    raw_capture_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period text,
    yoy double precision,
    summary text,
    doc_id bigint,
    basis text DEFAULT '时点'::text
);


ALTER TABLE public.vi_observation_base OWNER TO nocobase;

--
-- Name: TABLE vi_observation_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_observation_base IS '数据：每个指标每一期的数：统计时间、口径、数值、同比、来源文档和说明；引用【来源文档】【指标】【原始采集记录】；被【历史年度】【指标数值】【质量自检】引用。一行＝某个指标在某一期、某个口径下的一个数：自动采集的按天（股价、利率、水位），公司披露的按期（发电量、销量、新签合同额）。同一指标、同一口径、同一日期多次采集时取最后一次为“当前版本”；超出合理范围的为无效。报表计算的指标不在这里存数。出处只记一处：公司披露和历史补数关联“来源文档”，自动采集关联“原始采集记录”（只做解析与范围校验，不是财务核验）。';


--
-- Name: COLUMN vi_observation_base.obs_date; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.obs_date IS '对应日期：精确到日：时期指标填这段时期的最后一天（2026Q2 → 2026-06-30）；时点指标填观察当天（股价、水位为交易日，期末余额为期末日）';


--
-- Name: COLUMN vi_observation_base.value; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.value IS '数值';


--
-- Name: COLUMN vi_observation_base.collected_at; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.collected_at IS '采集时间';


--
-- Name: COLUMN vi_observation_base.metric_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.metric_id IS '指标（关联 指标）';


--
-- Name: COLUMN vi_observation_base.raw_capture_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.raw_capture_id IS '原始采集记录（关联 原始采集记录）';


--
-- Name: COLUMN vi_observation_base.period; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.period IS '统计时间：时期指标写这段时期：2026Q2（第二季度）、2026H1（上半年）、2025（全年）、2026M07（7 月）；时点指标写时点所在的报告期：2026Q2＝二季度末、2026M07＝7 月末；日度数据可留空，以对应日期为准';


--
-- Name: COLUMN vi_observation_base.yoy; Type: COMMENT; Schema: public; Owner: nocobase
