--
-- Name: COLUMN vi_observation_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.basis IS '口径：这一期数值覆盖的范围。时点指标只能用“时点”（某一天的值或期末余额）；时期指标用其余几种：单季、半年累计、前三季度累计、全年、年初至今累计（月度简报用）、滚动四季度（最近四个季度合计）（可选：时点、单季、半年累计、前三季度累计、全年、年初至今累计、滚动四季度）';


--
-- Name: vi_obs_current; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_obs_current AS
 SELECT o.metric_id,
    o.basis,
    o.period,
    o.obs_date,
    o.value,
    o.yoy,
    o.id
   FROM (public.vi_observation_base o
     JOIN public.vi_metric_base m ON ((m.id = o.metric_id)))
  WHERE ((o.value IS NOT NULL) AND (o.value >= COALESCE(m.valid_min, '-Infinity'::double precision)) AND (o.value <= COALESCE(m.valid_max, 'Infinity'::double precision)) AND (NOT (EXISTS ( SELECT 1
           FROM public.vi_observation_base o2
          WHERE ((o2.metric_id = o.metric_id) AND (o2.obs_date = o.obs_date) AND (NOT (o2.basis IS DISTINCT FROM o.basis)) AND ((o2.collected_at > o.collected_at) OR ((o2.collected_at IS NOT NULL) AND (o.collected_at IS NULL)) OR ((NOT (o2.collected_at IS DISTINCT FROM o.collected_at)) AND (o2.id > o.id))))))));


ALTER VIEW public.vi_obs_current OWNER TO nocobase;

