--
-- Name: vi_company_metric; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_company_metric AS
 SELECT company_id,
    metric_id,
    string_agg(DISTINCT usage, '、'::text ORDER BY usage) AS usages
   FROM ( SELECT vi_metric_base.company_id,
            vi_metric_base.id AS metric_id,
            '自有'::text AS usage
           FROM public.vi_metric_base
          WHERE (vi_metric_base.company_id IS NOT NULL)
        UNION ALL
         SELECT vi_company_base.id,
            vi_company_base.price_metric_id,
            '股价'::text
           FROM public.vi_company_base
          WHERE (vi_company_base.price_metric_id IS NOT NULL)
        UNION ALL
         SELECT vi_company_base.id,
            vi_company_base.price_fx_metric_id,
            '汇率折算'::text
           FROM public.vi_company_base
          WHERE (vi_company_base.price_fx_metric_id IS NOT NULL)
        UNION ALL
         SELECT j.company_id,
            l.metric_id,
            '重点跟踪'::text
           FROM (public.vi_lnk_judgment_metrics l
             JOIN public.vi_judgment_base j ON ((j.id = l.judgment_id)))
          WHERE (j.company_id IS NOT NULL)
        UNION ALL
         SELECT r.company_id,
            l.metric_id,
            '重点跟踪'::text
           FROM (public.vi_lnk_risk_metrics l
             JOIN public.vi_risk_base r ON ((r.id = l.risk_id)))
          WHERE (r.company_id IS NOT NULL)
        UNION ALL
         SELECT vi_lnk_company_macro_metrics.company_id,
            vi_lnk_company_macro_metrics.metric_id,
            '订阅'::text
           FROM public.vi_lnk_company_macro_metrics) u
  GROUP BY company_id, metric_id;


ALTER VIEW public.vi_company_metric OWNER TO nocobase;

--
-- Name: vi_company_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_company_calc AS
 SELECT c.id,
        CASE
            WHEN (c.price_fx_metric_id IS NULL) THEN l.value
            ELSE (l.value * fx.value)
        END AS latest_price,
    l.obs_date AS latest_price_date,
    l.value AS latest_price_raw,
    fx.value AS latest_fx,
    mu.macro_used
   FROM (((public.vi_company_base c
     LEFT JOIN LATERAL ( SELECT x.value,
            x.obs_date
           FROM public.vi_obs_current x
          WHERE (x.metric_id = c.price_metric_id)
          ORDER BY x.obs_date DESC
         LIMIT 1) l ON (true))
     LEFT JOIN LATERAL ( SELECT x.value
           FROM public.vi_obs_current x
          WHERE ((x.metric_id = c.price_fx_metric_id) AND (x.obs_date <= l.obs_date))
          ORDER BY x.obs_date DESC
         LIMIT 1) fx ON (true))
     LEFT JOIN LATERAL ( SELECT string_agg((((m.name || '（'::text) || cm.usages) || '）'::text), '；'::text ORDER BY m.id) AS macro_used
           FROM (public.vi_company_metric cm
             JOIN public.vi_metric_base m ON ((m.id = cm.metric_id)))
          WHERE ((cm.company_id = c.id) AND (m.company_id IS NULL))) mu ON (true));


ALTER VIEW public.vi_company_calc OWNER TO nocobase;

