--
-- Name: TABLE vi_epv_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_epv_base IS '调整后利润表：第二层：每块业务一张调整后利润表，一行一个项目，从报表利润一路算到可持续现金收益 E；引用【业务分部】【假设依据】【财务报表】；被【三层价值·业务】引用。收入 − 成本费用 ＝ 报表经营利润；± 税前调整 ＝ 调整后经营利润；− 所得税 ＝ 税后经营利润；± 税后调整（折旧摊销、维持性资本开支）；− 少数股东 ＝ E；盈利能力价值＝E÷门槛。每行的报表公式给出历年数，正常化值按取值方式算。';


--
-- Name: COLUMN vi_epv_base.sort; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.sort IS '排序';


--
-- Name: COLUMN vi_epv_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.name IS '项目';


--
-- Name: COLUMN vi_epv_base.section; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.section IS '段落：收入相加、成本费用相减得报表经营利润；税前调整、税后调整按方向加减；所得税、少数股东按比率；不计入＝只作对照（如利息收入、投资收益，它们在资产负债桥里单独计价）（可选：收入、成本费用、税前调整、所得税、税后调整、少数股东、不计入）';


--
-- Name: COLUMN vi_epv_base.direction; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.direction IS '方向：税前调整、税后调整用：加回还是扣除（可选：加、减）';


--
-- Name: COLUMN vi_epv_base.formula; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.formula IS '报表公式：历年数从「财务报表」按公式算：科目相加减，如“营运支出”“购建固定资产 + 购建无形资产及其他资产”；同名科目在多张报表时写“现金流量表：科目”。留空＝没有历史数（研究调整）';


--
-- Name: COLUMN vi_epv_base.method; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.method IS '取值方式：正常化值怎么取：金额＝填数（亿元）；占收入比例＝比例×正常化收入；最新年度、滚动四季度＝报表公式的最近一年或最近四个季度；历史平均＝起止年份的平均金额；历史平均占收入＝起止年份占收入比例的平均×正常化收入（周期业务的正常化）；比率＝所得税、少数股东的比率（可选：金额、占收入比例、最新年度、滚动四季度、历史平均、历史平均占收入、比率）';


--
-- Name: COLUMN vi_epv_base.value; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.value IS '数值：金额（亿元）或比例、比率（小数）';


--
-- Name: COLUMN vi_epv_base.from_year; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.from_year IS '起始年：历史平均用';


--
-- Name: COLUMN vi_epv_base.to_year; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.to_year IS '结束年：历史平均用';


--
-- Name: COLUMN vi_epv_base.note; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.note IS '说明';


--
-- Name: COLUMN vi_epv_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.company_id IS '公司（关联 公司）';


--
-- Name: COLUMN vi_epv_base.business_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_epv_base.business_id IS '业务（关联 业务分部）';


--
-- Name: vi_epv_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_epv_calc AS
 WITH l AS (
         SELECT e.id,
            e.sort,
            e.name,
            e.section,
            e.direction,
            e.formula,
            e.method,
            e.value,
            e.from_year,
            e.to_year,
            e.note,
            e.company_id,
            e.business_id,
            e.created_at,
            e.updated_at
           FROM public.vi_epv_base e
        ), h AS (
         SELECT l.id,
            l.business_id,
            l.section,
            (s_1.period)::integer AS y,
            s_1.value
           FROM (l
             CROSS JOIN LATERAL public.vi_stmt_series(l.company_id, l.formula) s_1(basis, period, period_end, value, yoy))
          WHERE ((NULLIF(btrim(l.formula), ''::text) IS NOT NULL) AND (s_1.basis = '全年'::text))
        ), t AS (
         SELECT DISTINCT ON (l.id) l.id,
            s_1.period,
            s_1.value
           FROM (l
             CROSS JOIN LATERAL public.vi_stmt_series(l.company_id, l.formula) s_1(basis, period, period_end, value, yoy))
          WHERE ((NULLIF(btrim(l.formula), ''::text) IS NOT NULL) AND (s_1.basis = '滚动四季度'::text))
          ORDER BY l.id, s_1.period_end DESC
        ), maxy AS (
         SELECT h.business_id,
            max(h.y) AS y
           FROM h
          GROUP BY h.business_id
        ), rh AS (
         SELECT h.business_id,
            h.y,
            sum(h.value) AS rev
           FROM h
          WHERE (h.section = '收入'::text)
          GROUP BY h.business_id, h.y
        ), base AS (
         SELECT l.id,
            l.business_id,
            l.section,
            l.direction,
            l.method,
            l.value,
            l.from_year,
            l.to_year,
                CASE l.method
                    WHEN '金额'::text THEN l.value
                    WHEN '最新年度'::text THEN ( SELECT h.value
                       FROM (h
                         JOIN maxy m ON (((m.business_id = h.business_id) AND (m.y = h.y))))
                      WHERE (h.id = l.id))
                    WHEN '滚动四季度'::text THEN ( SELECT t_1.value
                       FROM t t_1
                      WHERE (t_1.id = l.id))
                    WHEN '历史平均'::text THEN ( SELECT avg(h.value) AS avg
                       FROM h
                      WHERE ((h.id = l.id) AND ((h.y >= COALESCE(l.from_year, 0)) AND (h.y <= COALESCE(l.to_year, 9999)))))
                    ELSE NULL::double precision
                END AS v0,
            ( SELECT avg((h.value / NULLIF(rh.rev, (0)::double precision))) AS avg
                   FROM (h
                     JOIN rh ON (((rh.business_id = h.business_id) AND (rh.y = h.y))))
                  WHERE ((h.id = l.id) AND ((h.y >= COALESCE(l.from_year, 0)) AND (h.y <= COALESCE(l.to_year, 9999))))) AS avg_ratio
           FROM l
        ), rev AS (
         SELECT base.business_id,
                CASE
                    WHEN (count(*) = count(base.v0)) THEN sum(base.v0)
                    ELSE NULL::double precision
                END AS rev
           FROM base
          WHERE (base.section = '收入'::text)
          GROUP BY base.business_id
        ), amt AS (
         SELECT b.id,
            b.business_id,
            b.section,
            b.direction,
            b.method,
            b.value,
            b.from_year,
            b.to_year,
            b.v0,
            b.avg_ratio,
            r.rev,
                CASE
                    WHEN (b.section = ANY (ARRAY['所得税'::text, '少数股东'::text])) THEN NULL::double precision
                    WHEN ((b.method = '占收入比例'::text) AND (b.section <> '收入'::text)) THEN (b.value * r.rev)
                    WHEN ((b.method = '历史平均占收入'::text) AND (b.section <> '收入'::text)) THEN (b.avg_ratio * r.rev)
                    ELSE b.v0
                END AS amount,
                CASE
                    WHEN ((b.section = ANY (ARRAY['税前调整'::text, '税后调整'::text])) AND (b.direction = '减'::text)) THEN '-1'::integer
                    WHEN (b.section = ANY (ARRAY['税前调整'::text, '税后调整'::text])) THEN 1
                    ELSE NULL::integer
                END AS sgn
           FROM (base b
             LEFT JOIN rev r ON ((r.business_id = b.business_id)))
        ), sub AS (
         SELECT amt.business_id,
            ((sum(amt.amount) FILTER (WHERE (amt.section = '收入'::text)) - COALESCE(sum(amt.amount) FILTER (WHERE (amt.section = '成本费用'::text)), (0)::double precision)) + COALESCE(sum(((amt.sgn)::double precision * amt.amount)) FILTER (WHERE (amt.section = '税前调整'::text)), (0)::double precision)) AS ebit,
            COALESCE(sum(((amt.sgn)::double precision * amt.amount)) FILTER (WHERE (amt.section = '税后调整'::text)), (0)::double precision) AS post_adj,
            max(amt.value) FILTER (WHERE (amt.section = '所得税'::text)) AS tax_rate
           FROM amt
          GROUP BY amt.business_id
        ), hist AS (
         SELECT h.id,
            json_agg(json_build_array((h.y)::text, round((h.value)::numeric, 4)) ORDER BY h.y) AS j
           FROM (h
             JOIN maxy m ON ((m.business_id = h.business_id)))
          WHERE (h.y > (m.y - 5))
          GROUP BY h.id
        )
 SELECT a.id,
        CASE
            WHEN ((hist.j IS NOT NULL) OR (t.value IS NOT NULL)) THEN ((COALESCE((hist.j)::jsonb, '[]'::jsonb) ||
            CASE
                WHEN ((t.value IS NULL) OR (t.period ~~ '%Q4'::text)) THEN '[]'::jsonb
                ELSE jsonb_build_array(jsonb_build_array((('近四季（'::text || t.period) || '）'::text), round((t.value)::numeric, 4)))
            END))::text
            ELSE NULL::text
        END AS history,
        CASE
            WHEN (a.section = '所得税'::text) THEN (a.value * s.ebit)
            WHEN (a.section = '少数股东'::text) THEN (a.value * ((s.ebit * ((1)::double precision - s.tax_rate)) + s.post_adj))
            ELSE a.amount
        END AS normalized,
    (
        CASE
            WHEN (a.section = '所得税'::text) THEN (a.value * s.ebit)
            WHEN (a.section = '少数股东'::text) THEN (a.value * ((s.ebit * ((1)::double precision - s.tax_rate)) + s.post_adj))
            ELSE a.amount
        END / NULLIF(a.rev, (0)::double precision)) AS ratio
   FROM (((amt a
     LEFT JOIN sub s ON ((s.business_id = a.business_id)))
     LEFT JOIN hist ON ((hist.id = a.id)))
     LEFT JOIN t ON ((t.id = a.id)));


ALTER VIEW public.vi_epv_calc OWNER TO nocobase;

--
-- Name: vi_fit_score_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_fit_score_base (
    id bigint NOT NULL,
    dimension text,
    score integer,
    rationale text,
    counter text,
    sort integer,
    company_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.vi_fit_score_base OWNER TO nocobase;

--
-- Name: TABLE vi_fit_score_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_fit_score_base IS '价投适配度：按八个维度打分，看公司适不适合价值投资；引用【核心论点】；被【质量自检】引用。长坡、厚雪、慢变、护城河、再投资、财务质量、治理配置、可估值性，各 0—5 分。总分 32—40 适合复利框架，22—31 合适，21 以下通常不符合价值投资标准。';


--
-- Name: COLUMN vi_fit_score_base.dimension; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.dimension IS '维度（可选：长坡、厚雪、慢变、护城河、再投资、财务质量、治理配置、可估值性）';


--
-- Name: COLUMN vi_fit_score_base.score; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.score IS '评分（0—5）';


--
-- Name: COLUMN vi_fit_score_base.rationale; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.rationale IS '理由与证据';


--
-- Name: COLUMN vi_fit_score_base.counter; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.counter IS '反证';


--
-- Name: COLUMN vi_fit_score_base.sort; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.sort IS '排序';


--
-- Name: COLUMN vi_fit_score_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fit_score_base.company_id IS '公司（关联 公司）';


--
-- Name: vi_growth_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_growth_base (
    id bigint NOT NULL,
    growth double precision,
    ronic double precision,
    adv_years integer,
    note text,
    company_id bigint,
    business_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.vi_growth_base OWNER TO nocobase;

--
-- Name: TABLE vi_growth_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_growth_base IS '增长：第三层输入：每块业务、每个情景的增长与新增投资回报；引用【业务分部】【假设依据】【情景】；被【三层价值·业务】引用。优势年限内每年增长 g、再投入 g÷新增投资回报率 的收益，之后增长不再创造价值；新增投资回报率等于门槛时增长一分不值。不填或增长率为 0＝含增长价值等于盈利能力价值。';


--
-- Name: COLUMN vi_growth_base.growth; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.growth IS '增长率：优势期内每年的增长（小数，0.05＝5%）';


--
-- Name: COLUMN vi_growth_base.ronic; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.ronic IS '新增投资回报率：为增长新投入资本的税后回报；增长率不为 0 时必填（小数，0.05＝5%）';


--
-- Name: COLUMN vi_growth_base.adv_years; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.adv_years IS '优势年限：超额回报还能持续几年，之后增长不再创造价值；留空＝永续（要求增长率低于门槛）';


--
-- Name: COLUMN vi_growth_base.note; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.note IS '说明';


--
-- Name: COLUMN vi_growth_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.company_id IS '公司（关联 公司）';


--
-- Name: COLUMN vi_growth_base.business_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_growth_base.business_id IS '业务（关联 业务分部）';


--
-- Name: vi_gw_unit; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_gw_unit AS
 WITH lines AS (
         SELECT e.company_id,
            e.business_id,
            e.section,
            e.direction,
            e.value,
            e.method,
            c.normalized,
                CASE
                    WHEN ((e.section = ANY (ARRAY['税前调整'::text, '税后调整'::text])) AND (e.direction = '减'::text)) THEN '-1'::integer
                    ELSE 1
                END AS sgn
           FROM (public.vi_epv_base e
             JOIN public.vi_epv_calc c ON ((c.id = e.id)))
        ), agg AS (
         SELECT lines.company_id,
            lines.business_id,
            sum(lines.normalized) FILTER (WHERE (lines.section = '收入'::text)) AS revenue,
            COALESCE(sum(lines.normalized) FILTER (WHERE (lines.section = '成本费用'::text)), (0)::double precision) AS cost,
            COALESCE(sum(((lines.sgn)::double precision * lines.normalized)) FILTER (WHERE (lines.section = '税前调整'::text)), (0)::double precision) AS pre_adj,
            max(lines.value) FILTER (WHERE (lines.section = '所得税'::text)) AS tax_rate,
            COALESCE(sum(((lines.sgn)::double precision * lines.normalized)) FILTER (WHERE (lines.section = '税后调整'::text)), (0)::double precision) AS post_adj,
            COALESCE(max(lines.value) FILTER (WHERE (lines.section = '少数股东'::text)), (0)::double precision) AS minority_rate,
            count(*) FILTER (WHERE (lines.section = '收入'::text)) AS n_rev,
            count(*) FILTER (WHERE (lines.section = '所得税'::text)) AS n_tax,
            count(*) FILTER (WHERE (lines.section = '税后调整'::text)) AS n_post,
            string_agg(
                CASE
                    WHEN ((lines.section <> ALL (ARRAY['所得税'::text, '少数股东'::text, '不计入'::text])) AND (lines.normalized IS NULL)) THEN (('“'::text || COALESCE(NULLIF(lines.method, ''::text), '?'::text)) || '”取不到值'::text)
                    ELSE NULL::text
                END, '、'::text) AS bad_lines
           FROM lines
          GROUP BY lines.company_id, lines.business_id
        ), i AS (
         SELECT a.company_id,
            a.business_id,
            a.revenue,
            a.cost,
            a.pre_adj,
            a.tax_rate,
            a.post_adj,
            a.minority_rate,
            a.n_rev,
            a.n_tax,
            a.n_post,
            a.bad_lines,
            bz.code AS business_code,
            bz.name AS business_name,
            bz.sort AS business_sort,
            COALESCE(bz.capital_basis, '企业'::text) AS capital_basis,
            public.vi_hurdle() AS h,
            co.as_of,
            COALESCE(g.growth, (0)::double precision) AS g,
            g.ronic,
            g.adv_years
           FROM (((agg a
             JOIN public.vi_business_base bz ON ((bz.id = a.business_id)))
             LEFT JOIN public.vi_company_base co ON ((co.id = a.company_id)))
             LEFT JOIN public.vi_growth_base g ON ((g.business_id = a.business_id)))
        ), e AS (
         SELECT i.company_id,
            i.business_id,
            i.revenue,
            i.cost,
            i.pre_adj,
            i.tax_rate,
            i.post_adj,
            i.minority_rate,
            i.n_rev,
            i.n_tax,
            i.n_post,
            i.bad_lines,
            i.business_code,
            i.business_name,
            i.business_sort,
            i.capital_basis,
            i.h,
            i.as_of,
            i.g,
            i.ronic,
            i.adv_years,
            (i.revenue - i.cost) AS ebit_reported,
            ((i.revenue - i.cost) + i.pre_adj) AS ebit,
            concat_ws('、'::text,
                CASE
                    WHEN (i.h IS NULL) THEN '门槛（统一设置）'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((i.n_rev = 0) OR (i.revenue IS NULL)) THEN '收入'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((i.n_tax <> 1) OR (i.tax_rate IS NULL)) THEN '所得税（一行，填比率）'::text
                    ELSE NULL::text
                END, i.bad_lines,
                CASE
                    WHEN ((i.g <> (0)::double precision) AND (i.ronic IS NULL)) THEN '新增投资回报率'::text
                    ELSE NULL::text
                END) AS missing
           FROM i
        ), f AS (
         SELECT e.company_id,
            e.business_id,
            e.revenue,
            e.cost,
            e.pre_adj,
            e.tax_rate,
            e.post_adj,
            e.minority_rate,
            e.n_rev,
            e.n_tax,
            e.n_post,
            e.bad_lines,
            e.business_code,
            e.business_name,
            e.business_sort,
            e.capital_basis,
            e.h,
            e.as_of,
            e.g,
            e.ronic,
            e.adv_years,
            e.ebit_reported,
            e.ebit,
            e.missing,
            (e.ebit * e.tax_rate) AS tax,
            (e.ebit * ((1)::double precision - e.tax_rate)) AS nopat,
            (((e.ebit * ((1)::double precision - e.tax_rate)) + e.post_adj) * e.minority_rate) AS minority,
                CASE
                    WHEN (e.missing = ''::text) THEN (((e.ebit * ((1)::double precision - e.tax_rate)) + e.post_adj) * ((1)::double precision - e.minority_rate))
                    ELSE NULL::double precision
                END AS earnings
           FROM e
        ), v AS (
         SELECT f.company_id,
            f.business_id,
            f.revenue,
            f.cost,
            f.pre_adj,
            f.tax_rate,
            f.post_adj,
            f.minority_rate,
            f.n_rev,
            f.n_tax,
            f.n_post,
            f.bad_lines,
            f.business_code,
            f.business_name,
            f.business_sort,
            f.capital_basis,
            f.h,
            f.as_of,
            f.g,
            f.ronic,
            f.adv_years,
            f.ebit_reported,
            f.ebit,
            f.missing,
            f.tax,
            f.nopat,
            f.minority,
            f.earnings,
            public.vi_gw_pv(f.earnings, (0)::double precision, NULL::double precision, NULL::integer, NULL::integer, f.h) AS epv,
            public.vi_gw_pv(f.earnings, f.g, f.ronic, f.adv_years, NULL::integer, f.h) AS full_value
           FROM f
        )
 SELECT business_id AS id,
    company_id,
    business_id,
    business_code,
    business_name,
    business_sort,
    capital_basis,
    h,
    as_of,
    revenue,
    cost,
    ebit_reported,
    pre_adj,
    ebit,
    (ebit / NULLIF(revenue, (0)::double precision)) AS margin,
    tax,
    nopat,
    post_adj,
    minority,
    ((1)::double precision - minority_rate) AS attrib,
    earnings,
    ((ebit * ((1)::double precision - tax_rate)) + post_adj) AS pre_minority,
    epv,
    full_value,
    (full_value - epv) AS growth_value,
    g,
    ronic,
    adv_years,
    n_post,
    ((missing = ''::text) AND (full_value IS NOT NULL)) AS complete,
        CASE
            WHEN (missing <> ''::text) THEN ('缺 '::text || missing)
            WHEN (full_value IS NULL) THEN '永续增长率不低于门槛，不输出价值'::text
            ELSE NULL::text
        END AS note
   FROM v;


ALTER VIEW public.vi_gw_unit OWNER TO nocobase;

--
-- Name: vi_lnk_bs_item_judgments; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_lnk_bs_item_judgments (
    bs_item_id bigint NOT NULL,
    judgment_id bigint NOT NULL,
    "createdAt" timestamp with time zone NOT NULL,
    "updatedAt" timestamp with time zone NOT NULL
);


ALTER TABLE public.vi_lnk_bs_item_judgments OWNER TO nocobase;

--
-- Name: TABLE vi_lnk_bs_item_judgments; Type: COMMENT; Schema: public; Owner: nocobase
