--

COMMENT ON COLUMN public.vi_thesis_base.debated_on IS '辩论日期：做完正反立论与互相反驳后填写；竞争壁垒的“已辩论的论点数”按它统计';


--
-- Name: vi_moat_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_moat_calc AS
 SELECT m.id,
    x.latest_year AS check_latest_year,
    x.latest_value AS check_latest_value,
    x.result AS check_result,
    (( SELECT count(*) AS count
           FROM (public.vi_lnk_moat_theses l
             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
          WHERE ((l.moat_id = m.id) AND (t.debated_on IS NOT NULL))))::integer AS debate_count,
    ( SELECT string_agg(((t.code || ' '::text) || COALESCE(t.status, '未裁决'::text)), '；'::text ORDER BY t.id) AS string_agg
           FROM (public.vi_lnk_moat_theses l
             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
          WHERE ((l.moat_id = m.id) AND (t.debated_on IS NOT NULL))) AS debate_winner
   FROM (public.vi_moat_base m
     CROSS JOIN LATERAL public.vi_check_eval(m.company_id, m.check_metric, m.check_op, m.check_threshold, m.check_years) x(latest_year, latest_value, result));


ALTER VIEW public.vi_moat_calc OWNER TO nocobase;

--
-- Name: vi_observation_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_observation_calc AS
 SELECT o.id,
    m.unit,
    m.measure,
    m.source_kind,
    (row_number() OVER (PARTITION BY o.metric_id, o.basis, o.obs_date ORDER BY o.collected_at DESC NULLS LAST, o.id DESC) = 1) AS is_current,
    ((o.value IS NOT NULL) AND (o.value >= COALESCE(m.valid_min, '-Infinity'::double precision)) AND (o.value <= COALESCE(m.valid_max, 'Infinity'::double precision))) AS is_valid
   FROM (public.vi_observation_base o
     LEFT JOIN public.vi_metric_base m ON ((m.id = o.metric_id)));


ALTER VIEW public.vi_observation_calc OWNER TO nocobase;

--
-- Name: vi_risk_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_risk_calc AS
 SELECT r.id,
        CASE
            WHEN (s.score IS NULL) THEN NULL::text
            WHEN (s.score >= 6) THEN '重大'::text
            WHEN (s.score >= 3) THEN '重要'::text
            ELSE '一般'::text
        END AS level,
    ( SELECT string_agg(((t.code || ' '::text) || COALESCE(t.status, '未裁决'::text)), '；'::text ORDER BY t.code) AS string_agg
           FROM (public.vi_lnk_risk_theses l
             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
          WHERE (l.risk_id = r.id)) AS thesis_verdicts
   FROM (public.vi_risk_base r
     CROSS JOIN LATERAL ( SELECT (
                CASE r.probability
                    WHEN '高'::text THEN 3
                    WHEN '中'::text THEN 2
                    WHEN '低'::text THEN 1
                    ELSE NULL::integer
                END *
                CASE r.impact
                    WHEN '高'::text THEN 3
                    WHEN '中'::text THEN 2
                    WHEN '低'::text THEN 1
                    ELSE NULL::integer
                END) AS score) s);


ALTER VIEW public.vi_risk_calc OWNER TO nocobase;

--
-- Name: vi_thesis_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_thesis_calc AS
 SELECT t.id,
    x.latest_year AS check_latest_year,
    x.latest_value AS check_latest_value,
    x.result AS check_result,
    ( SELECT string_agg(((j.code || ' '::text) || COALESCE(j.status, '未定'::text)), '；'::text ORDER BY j.code) AS string_agg
           FROM (public.vi_lnk_judgment_theses l
             JOIN public.vi_judgment_base j ON ((j.id = l.judgment_id)))
          WHERE (l.thesis_id = t.id)) AS judgment_status
   FROM (public.vi_thesis_base t
     CROSS JOIN LATERAL public.vi_check_eval(t.company_id, t.check_metric, t.check_op, t.check_threshold, t.check_years) x(latest_year, latest_value, result));


ALTER VIEW public.vi_thesis_calc OWNER TO nocobase;

--
-- Name: vi_check; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_check AS
 WITH m AS (
         SELECT co.id AS company_id,
            co.name AS company_name,
            public.vi_hurdle() AS h,
            co.as_of,
            co.value_layer,
            cc.latest_price_date
           FROM (public.vi_company_base co
             LEFT JOIN public.vi_company_calc cc ON ((cc.id = co.id)))
        ), c AS (
         SELECT m.company_id,
            m.company_name,
            m.h,
            m.as_of,
            m.value_layer,
            m.latest_price_date,
            ( SELECT count(*) AS count
                   FROM (public.vi_collector_base k
                     JOIN public.vi_collector_calc kc USING (id))
                  WHERE kc.needs_alert) AS n_alert,
            ( SELECT count(*) AS count
                   FROM ((public.vi_observation_base o
                     JOIN public.vi_observation_calc oc USING (id))
                     JOIN public.vi_metric_base mt ON ((mt.id = o.metric_id)))
                  WHERE ((NOT oc.is_valid) AND ((mt.company_id = m.company_id) OR (mt.company_id IS NULL)))) AS n_invalid,
            ( SELECT count(*) AS count
                   FROM (public.vi_thesis_base th
                     JOIN public.vi_thesis_calc tc USING (id))
                  WHERE ((th.company_id = m.company_id) AND (tc.check_result ~~ '已触发%'::text))) AS n_falsified,
            ( SELECT count(*) AS count
                   FROM (public.vi_thesis_base th
                     JOIN public.vi_thesis_calc tc USING (id))
                  WHERE ((th.company_id = m.company_id) AND (tc.check_result <> '未设置'::text))) AS n_checked,
            ( SELECT count(*) AS count
                   FROM public.vi_moat_base mo
                  WHERE (mo.company_id = m.company_id)) AS n_moat,
