                  WHERE ((g_1.company_id = m.company_id) AND (COALESCE(g_1.growth, (0)::double precision) > (0)::double precision) AND (g_1.ronic > m.h) AND (NOT (EXISTS ( SELECT 1
                           FROM ((((public.vi_lnk_growth_judgments gj
