                END,COALESCE((('股权口径（利润已扣利息）的业务，但资产负债重估里还有“有息负债”进资产负债桥，债务会扣两次：'::text || g.debt_in_enterprise) || '。股权口径的公司把有息负债归为经营负债'::text), '企业口径：有息负债在资产负债桥里扣；股权口径：有息负债归为经营负债'::text)), (28,'G08'::text,'维持性投入已估'::text,
                CASE
                    WHEN (g.no_maint IS NULL) THEN '通过'::text
                    ELSE '提示'::text
                END,COALESCE(('调整后利润表没有税后调整（折旧摊销、维持性资本开支），按两者相等处理：'::text || g.no_maint), '每块业务都估了折旧摊销与维持性资本开支'::text)), (29,'G09'::text,'主估值层'::text,
                CASE
                    WHEN (g.value_layer IS NULL) THEN '提示'::text
                    WHEN ((g.value_layer = '资产价值'::text) AND (g.av_na IS NOT NULL)) THEN '阻断'::text
                    ELSE '通过'::text
                END,
                CASE
                    WHEN (g.value_layer IS NULL) THEN '没选主估值层：只展示三层，不给结论'::text
                    WHEN ((g.value_layer = '资产价值'::text) AND (g.av_na IS NOT NULL)) THEN '主估值层是资产价值，但公司的资产价值口径是“不适用”'::text
                    ELSE ('主估值层：'::text || g.value_layer)
                END)) x(k, code, name, result, detail));


