--
-- Name: vi_stmt_cache; Type: MATERIALIZED VIEW; Schema: public; Owner: nocobase
--

CREATE MATERIALIZED VIEW public.vi_stmt_cache AS
 SELECT m.id AS metric_id,
    s.basis,
    s.period,
    s.period_end,
    s.value,
    s.yoy
   FROM (public.vi_metric_base m
     CROSS JOIN LATERAL public.vi_stmt_series(m.company_id, m.formula) s(basis, period, period_end, value, yoy))
  WHERE ((m.source_kind = '报表计算'::text) AND (NULLIF(btrim(m.formula), ''::text) IS NOT NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.vi_stmt_cache OWNER TO nocobase;

--
-- Name: vi_series; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_series AS
 SELECT o.metric_id,
    o.basis,
    o.period,
    o.obs_date,
    o.value,
    o.yoy,
    o.id AS observation_id
   FROM public.vi_obs_current o
UNION ALL
 SELECT s.metric_id,
    s.basis,
    s.period,
    s.period_end AS obs_date,
    s.value,
    s.yoy,
    NULL::bigint AS observation_id
   FROM (public.vi_stmt_cache s
     LEFT JOIN public.vi_observation_base o ON (((o.metric_id = s.metric_id) AND (o.basis = s.basis) AND (o.period = s.period))))
  WHERE (o.id IS NULL);


ALTER VIEW public.vi_series OWNER TO nocobase;

--
-- Name: vi_disclosed; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_disclosed AS
 SELECT x.observation_id AS id,
    m.company_id,
    x.period,
    x.obs_date AS period_end,
    x.basis AS period_kind,
    m.name AS line_item,
    x.value,
    m.unit,
    x.yoy,
    o.summary,
    o.doc_id AS source_id,
    m.id AS metric_id,
    m.code AS metric_code
   FROM ((public.vi_series x
     JOIN public.vi_metric_base m ON ((m.id = x.metric_id)))
     LEFT JOIN public.vi_observation_base o ON ((o.id = x.observation_id)))
  WHERE ((m.company_id IS NOT NULL) AND (m.source_kind <> '自动采集'::text));


