--
-- Name: TABLE vi_event_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_event_base IS '事项：一件事一行（并购、监管变化、竞争格局、资本运作等），短名称加简介；具体的可核验侧面是挂在它下面的定性事实；被【定性事实】引用。名称用短名词短语，不带数字；简介三五句讲清来龙去脉、关键条款和现状。每个侧面（日期、来源、核验状态各自独立）记在定性事实里，上层判断引用侧面；零散的一次性事实可以不挂事项。';


--
-- Name: COLUMN vi_event_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_event_base.name IS '事项：短名称，不带数字，如“喜马拉雅收购”';


--
-- Name: COLUMN vi_event_base.category; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_event_base.category IS '类别（可选：经营、财务、资本开支、分红、债务、政策、治理、竞争、估值方法、其他）';


--
-- Name: COLUMN vi_event_base.status; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_event_base.status IS '状态（可选：进行中、已完成、持续、待观察）';


--
-- Name: COLUMN vi_event_base.period; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_event_base.period IS '时间：发生或持续的时间，如 2026、2018—2025';


--
-- Name: COLUMN vi_event_base.summary; Type: COMMENT; Schema: public; Owner: nocobase
--

