--
-- Name: vi_fact_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_fact_base (
    id bigint NOT NULL,
    title text,
    category text,
    statement text,
    period text,
    as_of date,
    verify_status text,
    notes text,
    company_id bigint,
    source_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    event_id bigint
);


ALTER TABLE public.vi_fact_base OWNER TO nocobase;

--
-- Name: TABLE vi_fact_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_fact_base IS '定性事实：数字以外、会改变判断的事实：制度监管、合作授权、并购与资本运作、人事、诉讼、管理层表态、竞争对手动作，以及外部观点与估值参照；引用【来源文档】【事项】；被【商业模式拆解】【产业链与五力】【竞争对手】【竞争壁垒】【核心论点】【风险分析】【假设依据】【资产估值与调整】【经营分部估值】【逐年假设】引用。一条可核验的定性事实，通常是某个事项的一个侧面。按期重复的数字不放这里：它们在「指标／数据」里，上层判断用“依据指标”引用；一次性的数字（并购对价、回购额度）可以写进事实。';


