--
-- Name: vi_gw_value; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_gw_value AS
 WITH s AS (
         SELECT co.id AS company_id,
            co.name AS company_name,
            co.shares,
            public.vi_hurdle() AS h,
            co.as_of,
            co.value_layer,
            COALESCE(co.av_basis, '调整后净资产'::text) AS av_basis,
            co.repro_cost,
            cc.latest_price,
            cc.latest_price_date
           FROM (public.vi_company_base co
             LEFT JOIN public.vi_company_calc cc ON ((cc.id = co.id)))
          WHERE (EXISTS ( SELECT 1
                   FROM public.vi_epv_base e
                  WHERE (e.company_id = co.id)))
        ), br AS (
         SELECT b.company_id,
            sum(c.value_signed) AS bridge,
            count(*) FILTER (WHERE (c.book IS NULL)) AS n_missing
           FROM (public.vi_bs_item_base b
             JOIN public.vi_bs_item_calc c ON ((c.id = b.id)))
          WHERE (c.role = '资产负债桥'::text)
          GROUP BY b.company_id
        ), op AS (
         SELECT b.company_id,
            sum(c.book_signed) AS book_capital,
            sum(c.value_signed) AS adj_capital,
            count(*) FILTER (WHERE (c.book IS NULL)) AS n_missing
           FROM (public.vi_bs_item_base b
             JOIN public.vi_bs_item_calc c ON ((c.id = b.id)))
          WHERE (c.role = '经营资本'::text)
          GROUP BY b.company_id
        ), u AS (
         SELECT vi_gw_unit.company_id,
            sum(vi_gw_unit.epv) AS epv_total,
            sum(vi_gw_unit.full_value) AS full_total,
            ((1)::double precision - COALESCE((sum(vi_gw_unit.minority) / NULLIF(sum(vi_gw_unit.pre_minority), (0)::double precision)), (0)::double precision)) AS av_attrib,
            bool_and(vi_gw_unit.complete) AS complete,
            string_agg(((vi_gw_unit.business_name || '：'::text) || vi_gw_unit.note), '；'::text ORDER BY vi_gw_unit.business_sort) FILTER (WHERE (NOT vi_gw_unit.complete)) AS missing,
            array_agg(vi_gw_unit.earnings) AS e,
            array_agg(vi_gw_unit.g) AS g,
            array_agg(vi_gw_unit.ronic) AS ro,
            array_agg(vi_gw_unit.adv_years) AS n,
            array_agg(NULL::integer) AS l
           FROM public.vi_gw_unit
          GROUP BY vi_gw_unit.company_id
        ), x AS (
         SELECT s.company_id,
            s.company_name,
            s.shares,
            s.h,
            s.as_of,
            s.value_layer,
            s.av_basis,
            s.repro_cost,
            s.latest_price,
            s.latest_price_date,
            u.epv_total,
            u.full_total,
            u.av_attrib,
            op.book_capital,
            op.adj_capital,
                CASE s.av_basis
                    WHEN '不适用'::text THEN NULL::double precision
                    WHEN '重建成本'::text THEN (s.repro_cost * u.av_attrib)
                    ELSE
                    CASE
                        WHEN (COALESCE(op.n_missing, (0)::bigint) = 0) THEN (op.adj_capital * u.av_attrib)
                        ELSE NULL::double precision
                    END
                END AS av_total,
            u.missing,
            u.e,
            u.g,
            u.ro,
            u.n,
            u.l,
            COALESCE(br.bridge, (0)::double precision) AS bridge,
            COALESCE(br.n_missing, (0)::bigint) AS bridge_missing,
            (COALESCE(u.complete, false) AND (COALESCE(br.n_missing, (0)::bigint) = 0) AND (s.shares > (0)::double precision) AND (s.as_of IS NOT NULL)) AS complete,
            GREATEST((0)::numeric, (((public.vi_today() - s.as_of))::numeric / 365.25)) AS elapsed
           FROM (((s
             LEFT JOIN u ON ((u.company_id = s.company_id)))
             LEFT JOIN br ON ((br.company_id = s.company_id)))
             LEFT JOIN op ON ((op.company_id = s.company_id)))
        ), z AS (
         SELECT x.company_id,
            x.company_name,
            x.shares,
            x.h,
            x.as_of,
            x.value_layer,
            x.av_basis,
            x.repro_cost,
            x.latest_price,
            x.latest_price_date,
            x.epv_total,
            x.full_total,
            x.av_attrib,
            x.book_capital,
            x.adj_capital,
            x.av_total,
            x.missing,
            x.e,
            x.g,
            x.ro,
            x.n,
            x.l,
            x.bridge,
            x.bridge_missing,
            x.complete,
            x.elapsed,
            (power(((1)::double precision + x.h), (x.elapsed)::double precision) / x.shares) AS k,
                CASE
                    WHEN x.complete THEN public.vi_gw_irr(x.e, x.g, x.ro, x.n, x.l, false, x.bridge, x.shares, (x.elapsed)::double precision, x.latest_price)
                    ELSE NULL::double precision
                END AS irr_epv,
                CASE
                    WHEN x.complete THEN public.vi_gw_irr(x.e, x.g, x.ro, x.n, x.l, true, x.bridge, x.shares, (x.elapsed)::double precision, x.latest_price)
                    ELSE NULL::double precision
                END AS irr_full
           FROM x
        ), y AS (
         SELECT z.company_id,
            z.company_name,
            z.shares,
            z.h,
            z.as_of,
            z.value_layer,
            z.av_basis,
            z.repro_cost,
            z.latest_price,
            z.latest_price_date,
            z.epv_total,
            z.full_total,
            z.av_attrib,
            z.book_capital,
            z.adj_capital,
            z.av_total,
            z.missing,
            z.e,
            z.g,
            z.ro,
            z.n,
            z.l,
            z.bridge,
            z.bridge_missing,
            z.complete,
            z.elapsed,
            z.k,
            z.irr_epv,
            z.irr_full,
                CASE
                    WHEN z.complete THEN ((z.av_total + z.bridge) * z.k)
                    ELSE NULL::double precision
                END AS av_ps,
                CASE
                    WHEN z.complete THEN ((z.epv_total + z.bridge) * z.k)
                    ELSE NULL::double precision
                END AS epv_ps,
                CASE
                    WHEN z.complete THEN ((z.full_total + z.bridge) * z.k)
                    ELSE NULL::double precision
                END AS full_ps
           FROM z
        ), v AS (
         SELECT y.company_id,
            y.company_name,
            y.shares,
            y.h,
            y.as_of,
            y.value_layer,
            y.av_basis,
            y.repro_cost,
            y.latest_price,
            y.latest_price_date,
            y.epv_total,
            y.full_total,
            y.av_attrib,
            y.book_capital,
            y.adj_capital,
            y.av_total,
            y.missing,
            y.e,
            y.g,
            y.ro,
            y.n,
            y.l,
            y.bridge,
            y.bridge_missing,
            y.complete,
            y.elapsed,
            y.k,
            y.irr_epv,
            y.irr_full,
            y.av_ps,
            y.epv_ps,
            y.full_ps,
                CASE y.value_layer
                    WHEN '资产价值'::text THEN y.av_ps
                    WHEN '盈利能力价值'::text THEN y.epv_ps
                    WHEN '含增长价值'::text THEN y.full_ps
                    ELSE NULL::double precision
                END AS value_ps,
                CASE y.value_layer
                    WHEN '盈利能力价值'::text THEN y.irr_epv
                    WHEN '含增长价值'::text THEN y.irr_full
                    ELSE NULL::double precision
                END AS implied_irr
           FROM y
        )
 SELECT company_id AS id,
    company_id,
    company_name,
    h AS hurdle,
    as_of,
    shares,
    bridge,
    av_basis,
    book_capital,
    adj_capital,
    av_attrib,
    av_total,
    epv_total,
    full_total,
    av_ps,
    epv_ps,
    full_ps,
    value_layer,
    value_ps,
    latest_price AS market_price,
    latest_price_date AS market_date,
    irr_epv,
    irr_full,
    implied_irr,
    complete,
        CASE
            WHEN (NOT complete) THEN ('输入不完整：'::text || COALESCE(missing,
            CASE
                WHEN (bridge_missing > 0) THEN '资产负债桥有科目在报表里找不到'::text
                WHEN (as_of IS NULL) THEN '公司没填估值截至日'::text
                ELSE '股本未填'::text
            END))
            ELSE (format('主估值层：%s。按门槛 %s，今天每股：资产价值 %s、盈利能力价值 %s、含增长价值 %s 元。'::text, COALESCE(value_layer, '未选'::text), public.vi_pct(h, 1), public.vi_fmt(av_ps), public.vi_fmt(epv_ps), public.vi_fmt(full_ps)) ||
            CASE
                WHEN (latest_price IS NULL) THEN '暂无市价。'::text
                ELSE ((format('市价 %s 元'::text, public.vi_fmt(latest_price)) ||
                CASE
                    WHEN ((av_ps IS NOT NULL) AND (latest_price <= av_ps)) THEN '，低于资产价值'::text
                    WHEN (latest_price <= epv_ps) THEN '，低于盈利能力价值：不为增长付钱'::text
                    WHEN (latest_price <= full_ps) THEN '，在盈利能力价值与含增长价值之间：为部分增长付钱'::text
                    ELSE '，高于含增长价值'::text
                END) || format('；隐含年化回报：不增长 %s、含增长 %s（门槛 %s）。'::text, public.vi_pct(irr_epv, 1), public.vi_pct(irr_full, 1), public.vi_pct(h, 1)))
            END)
        END AS conclusion
   FROM v;


