--
-- Name: vi_metric_value; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_metric_value AS
 SELECT
        CASE
            WHEN (x.observation_id IS NOT NULL) THEN x.observation_id
            ELSE (- ((x.metric_id * 1000000) + (abs(hashtext(((x.basis || '|'::text) || x.period))) % 1000000)))
        END AS id,
    x.metric_id,
    m.company_id,
    x.period,
    x.basis,
    x.obs_date,
    x.value,
    x.yoy,
    m.unit,
        CASE
            WHEN (x.observation_id IS NULL) THEN '报表计算'::text
            ELSE '录入'::text
        END AS origin,
    o.summary,
    o.doc_id,
    d.title AS doc_title
   FROM (((public.vi_series x
     JOIN public.vi_metric_base m ON ((m.id = x.metric_id)))
     LEFT JOIN public.vi_observation_base o ON ((o.id = x.observation_id)))
     LEFT JOIN public.vi_source_base d ON ((d.id = o.doc_id)));


