    b.status,
    b.confidence,
    b.bull_case,
    b.bear_case,
    b.bull_rebuttal,
    b.bear_rebuttal,
    b.verdict,
    b.decisive_evidence,
    b.mind_changer,
    b.model_impact,
    b.external_view,
    b.debated_on,
    b.check_metric,
    b.check_op,
    b.check_threshold,
    b.check_years,
    b.company_id,
    c.check_latest_year,
    c.check_latest_value,
    c.check_result,
    c.judgment_status,
    b.updated_at
   FROM (public.vi_thesis_base b
     LEFT JOIN public.vi_thesis_calc c ON ((c.id = b.id)));


ALTER VIEW public.vi_thesis OWNER TO nocobase;

