--
-- Name: vi_value_chain_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_value_chain_base (
    id bigint NOT NULL,
    code text,
    "position" text,
    participant text,
    role text,
    force text,
    power text,
    effect text,
    trend text,
    profit_share text,
    analysis text,
    counter text,
    company_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.vi_value_chain_base OWNER TO nocobase;

--
-- Name: TABLE vi_value_chain_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_value_chain_base IS '产业链与五力：产业链上下游各方对公司的议价力强弱；引用【定性事实】【竞争对手】【指标】。上下游各环节是谁、拿走多少利润、对公司的议价力强弱；每行同时标注属于波特五力中的哪一种力量。同业、替代品、潜在进入者这几行只评估力量强弱，具体对手的规模与打法写在竞争对手表，并在“相关对手”里关联。';


--
-- Name: COLUMN vi_value_chain_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.code IS '编号：V1 固定是本公司环节，其余各方从 V2 起编';


--
-- Name: COLUMN vi_value_chain_base."position"; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base."position" IS '环节（可选：上游供给、本公司环节、下游客户、渠道与流量、互补方、替代品、潜在进入者、同业竞争、监管）';


--
-- Name: COLUMN vi_value_chain_base.participant; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.participant IS '参与者';


--
-- Name: COLUMN vi_value_chain_base.role; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.role IS '提供或购买什么';


--
-- Name: COLUMN vi_value_chain_base.force; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.force IS '五力归类（可选：供应商议价能力、买方议价能力、新进入者威胁、替代品威胁、行业内竞争、不适用）';


--
-- Name: COLUMN vi_value_chain_base.power; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.power IS '力量强弱（可选：强、中、弱）';


--
-- Name: COLUMN vi_value_chain_base.effect; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.effect IS '对公司（可选：有利、中性、不利）';


--
-- Name: COLUMN vi_value_chain_base.trend; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.trend IS '趋势（可选：增强、稳定、减弱）';


--
-- Name: COLUMN vi_value_chain_base.profit_share; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.profit_share IS '利润池或成本占比：如 版权成本约占收入 45%—55%';


--
-- Name: COLUMN vi_value_chain_base.analysis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.analysis IS '分析';


--
-- Name: COLUMN vi_value_chain_base.counter; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.counter IS '反面证据';


--
-- Name: COLUMN vi_value_chain_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_value_chain_base.company_id IS '公司（关联 公司）';


--
-- Name: vi_value_chain; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_value_chain AS
 SELECT id,
    code,
    "position",
    participant,
    role,
    force,
    power,
    effect,
    trend,
    profit_share,
    analysis,
    counter,
    company_id,
    updated_at
   FROM public.vi_value_chain_base b;


ALTER VIEW public.vi_value_chain OWNER TO nocobase;

