Hours();\\r\\n\\t\\t\\t\\tvar minute = now.getMinutes();\\r\\n\\t\\t\\t\\tvar second = now.getSeconds();\\r\\n\\t\\t\\t\\treturn PrefixInteger(date, 2) + \\"日 \\" + PrefixInteger(hour, 2) + \\"时\\"+PrefixInteger(minute, 2) + \\"分\\";;\\r\\n\\r\\n\\t\\t\\t}\\r\\n\\t\\t\\tfunction PrefixInteger(num, n) {\\r\\n\\t\\t\\t\\treturn(Array(n).join(0) + num).slice(-n);\\r\\n\\t\\t\\t}\\r\\n\\r\\nwindow.addEventListener('message',function(rs){\\r\\n    var pointdata=rs.data;\\r\\nif(pointdata=='refresh'){\\r\\n     window.location.reload();\\r\\n}else{\\r\\nconsole.log(pointdata);\\r\\n}\\r\\n})\\r\\n</script>\\r\\n\\t</body>\\r\\n\\r\\n</html>\\r\\n","headers":{"Server":"nginx","Set-Cookie":"WJSESSIONID=CB0105C2D935FBC15989E65147EF9A97; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.238; local=123.58.10.238:51702; remote=219.140.196.72:80","X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Tue, 22 Sep 2026 10:30:15 GMT"},"status_code":200,"$startTime":1790073009403,"$endTime":1790073010258}	recvvWzUKvKU0Y
