>\\r\\n\\t\\t\\t\\t    <th style=\\"border-left:1px solid #000000\\">7<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t    <th style=\\"border-left:1px solid #000000\\">10<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t    <th style=\\"border-left:1px solid #000000\\">30<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t</tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债国债收益率曲线</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">0.9202 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.1865</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.2002</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.2347</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.2894</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4073</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5046</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6807</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">2.1100</td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债商业银行普通债收益率曲线(AAA)</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">1.3400 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4325</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4528</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4831</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5588</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5653</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6981</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.8760</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">2.3025</td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债中短期票据收益率曲线(AAA)</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">1.4700 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4800</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4999</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5114</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6301</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6910</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.7939</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.9704</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\"></td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t</table>\\r\\n\\t\\t</div>\\r\\n\\t\\t<div id=\\"zhu\\"> <!-- 注：表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率 -->注：&nbsp;表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率</div>\\r\\n\\t\\t<div id=\\"font1\\">\\r\\n\\t\\t\\t\\r\\n\\t\\t\\t\\t<div style=\\"font-weight:bold; text-align: center;\\">\\r\\n\\t\\t               <!-- 国债及其他收益率曲线简介 -->国债及其他债券收益率曲线简介\\r\\n\\t\\t    \\t</div>\\r\\n\\t\\t\\t\\r\\n\\t\\t      <div>\\r\\n\\t\\t         &nbsp; &nbsp; <!-- 国债及其他收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。\\r\\n\\t\\t                            其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债曲线样本包括同业存单和商业银行债券；AAA级中短期票据曲线样本包括AAA级超短期融资券、短期融资券和中期票据 -->\\r\\n\\t\\t                            国债及其他债券收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债收益率曲线样本包括同业存单和商业银行债券；AAA级中短期票据收益率曲线样本包括AAA级超短期融资券、短期融资券和中期票据。\\r\\n\\t\\t      </div>\\r\\n\\t\\t      <div>\\r\\n\\t\\t        &nbsp; &nbsp; <!-- 中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、\\r\\n\\t\\t                       货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30 -->\\r\\n\\t\\t                           中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30。\\r\\n\\t\\t     </div>\\r\\n\\t\\t</div>\\r\\n\\t</div>\\r\\n\\t<input type=\\"hidden\\" id=\\"locale\\" value=\\"cn_ZH\\">\\r\\n</body>\\r\\n\\r\\n<script type=\\"text/javascript\\">\\r\\n\\r\\n    Highcharts.setOptions({\\r\\n        global: {\\r\\n            useUTC: false\\r\\n        },\\r\\n    });\\r\\n    var chart = null;\\r\\n    var xData=new Array();\\r\\n    var options = {\\r\\n        chart : {\\r\\n            exporting : {\\r\\n                enabled : true //用来设置是否显示‘打印’,'导出'等功能按钮，不设置时默认为显示\\r\\n            },\\r\\n            renderTo : 'graph',\\r\\n            type: 'line',\\r\\n            marginBottom : 90,\\r\\n            marginTop : 5,\\r\\n            marginLeft : 50,\\r\\n        },\\r\\n        title : {\\r\\n            text : ''\\r\\n        },\\r\\n        xAxis : {\\r\\n            labels:{\\r\\n                style:{\\r\\n                    fontSize:'10px',\\r\\n                    fontFamily: \\"宋体\\",\\r\\n                    color: \\"#333333\\",\\r\\n                }\\r\\n            },\\r\\n            crosshair: {\\r\\n                width: 1,\\r\\n                color: '#CC0000'\\r\\n            },\\r\\n            categories:xData,\\r\\n            tickPositions: [0,10, 20,30, 50,70,110],\\r\\n            tickWidth : 1,\\r\\n            gridLineWidth : 1,\\r\\n            lineWidth : 1,\\r\\n            lineColor : 'black',\\r\\n            showFirstLabel : true,\\r\\n            showLastLable : true,\\r\\n            tickLength : 0,\\r\\n        },\\r\\n\\r\\n        yAxis : [ {\\r\\n            labels : {\\r\\n                format : '{value:.,0f}',\\r\\n                padding : 50,\\r\\n                x : -10,\\r\\n                formatter : function(){\\r\\n                    return this.value.toFixed(2);//这里是两位小数，你要几位小数就改成几\\r\\n                },\\r\\n                style:{\\r\\n                    fontWeight:\\"normal\\",\\r\\n                    fontSize: \\"10px\\",\\r\\n                    fontFamily: \\"宋体\\",\\r\\n                    color: \\"#333333\\",\\r\\n                }\\r\\n            },\\r\\n            title : {\\r\\n                text : '(%)',\\r\\n                align: 'high',\\r\\n                offset: 5,\\r\\n                rotation:0,\\r\\n                y: 85,\\r\\n                x: -30,\\r\\n                style:{\\r\\n                    fontWeight:\\"normal\\",\\r\\n                    fontSize: \\"10px\\",\\r\\n                    fontFamily: \\"宋体\\",\\r\\n                    color: \\"#333333\\",\\r\\n                }\\r\\n            },\\r\\n            tickPixelInterval: 50,\\r\\n            allowDecimals : true,//是否显示小数\\r\\n            showFirstLabel : true,\\r\\n            tickPosition : 'outside',\\r\\n            tickLength : 3,\\r\\n            opposite : false,//设置y轴在对面显示\\r\\n            lineWidth : 1,//设置y轴的线宽\\r\\n            tickWidth : 1,\\r\\n            tickColor : 'black',\\r\\n            lineColor : 'black',\\r\\n        } ],\\r\\n\\r\\n        legend : {\\r\\n            enabled : true,\\r\\n            align: 'left',\\r\\n            layout: 'vertical',\\r\\n            floating: true,\\r\\n            itemMarginTop: 3,\\r\\n            x: 45,\\r\\n            y: 10,\\r\\n            itemStyle: {\\r\\n                fontWeight:\\"normal\\",\\r\\n                fontSize: \\"12px\\",\\r\\n                fontFamily: \\"宋体\\",\\r\\n                color: \\"#333333\\",\\r\\n                cursor: \\"default\\",\\r\\n            },\\r\\n        },\\r\\n        credits : {\\r\\n            enabled : false //去掉higcharts.com\\r\\n        },\\r\\n        tooltip : {\\r\\n            shared : false,\\r\\n            split : true,\\r\\n            animation : false,\\r\\n            shape : 'square',\\r\\n            crosshairs : {\\r\\n                width : 1,\\r\\n                color : 'red'\\r\\n            },\\r\\n            distance : 3,//距离某个点的距离\\r\\n            useHTML : true,\\r\\n            borderWidth : 1,\\r\\n            headerFormat : '<small style=\\"background-color:#DC143C\\">{point.key}</small><table border=\\"5\\">',\\r\\n            pointFormat : '<tr><td style=\\"text-align: right,color:{point.color}\\">{point.y:.4f}%</td></tr>',\\r\\n            footerFormat : '</table>',\\r\\n        },\\r\\n        plotOptions : {\\r\\n            series: {\\r\\n                animation:false,\\r\\n                states:{\\r\\n                    hover:{\\r\\n                        lineWidthPlus: 0\\r\\n                    },\\r\\n                },\\r\\n                marker:{\\r\\n                    symbol:'circle',\\r\\n                    enabled:true,\\r\\n                    radius:0.1\\r\\n                },\\r\\n                connectNulls:true,//连接空点\\r\\n            },\\r\\n        },\\r\\n        series : []\\r\\n    }\\r\\n    function query(){\\r\\n        queryGjqxInfo();\\r\\n\\r\\n        var workTime=document.getElementById(\\"gzr\\").value;\\r\\n\\t\\tvar locale = document.getElementById('locale').value;\\r\\n        var url = \\"/cbweb-pbc-web/pbc/query?&workTime=\\"+workTime+\\"&locale=\\"+locale;\\r\\n\\r\\n        $.ajax({\\r\\n            type : \\"post\\",\\r\\n            url : url,\\r\\n            cache : false,\\r\\n            success : function(data) {\\r\\n                createGraph(data);\\r\\n            },\\r\\n            error : function() {\\r\\n                alert(LoadingDataFailedMsg);\\r\\n                $('#graph').html(\\"\\");\\r\\n                return;\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n\\r\\n    var url = window.location.href;\\r\\n    var locale=url.substring(url.indexOf(\\"=\\") + 1, url.length).split('&');\\r\\n\\tif ( locale !== 'en_US') {\\r\\n\\t\\tlocale = 'zh_CN'\\r\\n\\t}\\r\\n\\r\\n    function queryGjqxInfo(){\\r\\n        var workTime = [document.getElementById(\\"gzr\\").value];\\r\\n\\t\\tvar locale = document.getElementById('locale').value;\\r\\n        var url = \\"/cbweb-pbc-web/pbc/queryGjqxInfo?&workTime=\\"+workTime+\\"&locale=\\"+locale;\\r\\n\\r\\n        $.ajax({\\r\\n            type : \\"post\\",\\r\\n            url : url,\\r\\n            cache : false,\\r\\n            dataType : \\"html\\",\\r\\n            success : function(data) {\\r\\n                $(\\"#gjqxData\\").html(data);\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n\\r\\n\\r\\n\\r\\n    function historyQuery(){\\r\\n    \\tvar localeValue = document.getElementById('locale').value;\\r\\n\\t\\tif(localeValue ==\\"en_US\\" ){\\r\\n\\t\\t\\twindow.open ('/cbweb-pbc-web/pbc/showHistory?locale='+localeValue,'newwindow','height=550,width=1145,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no');\\r\\n\\t\\t}else{\\r\\n\\t\\t\\twindow.open ('/cbweb-pbc-web/pbc/showHistory?locale=zh_CN','newwindow','height=550,width=980,top=0,left=0,toolbar=no,menubar=no,scrollbars=yes,resizable=yes,location=no,status=no');\\r\\n\\t\\t}\\r\\n    }\\r\\n\\r\\n\\r\\n\\r\\n    function showInfo(msgInfo,title){\\r\\n        alert(msgInfo);\\r\\n    }\\r\\n\\r\\n    var zero;\\r\\n    var year;\\r\\n    var month;\\r\\n    var dataNullMsg;\\r\\n    var LoadingDataFailedMsg;\\r\\n    $(document).ready(function(){\\r\\n        if(false){\\r\\n            zero = \\"O/N\\";\\r\\n            year = \\"Y\\";\\r\\n            month = \\"M\\";\\r\\n            dataNullMsg = \\"No matched yield curve is found,please trying other searching criteria.\\";\\r\\n            LoadingDataFailedMsg = \\"Loading data failed\\";\\r\\n        }else{\\r\\n            zero = \\"0\\";\\r\\n            year = \\"年\\";\\r\\n            month = \\"月\\";\\r\\n            dataNullMsg = \\"没有查询到曲线,请重新输入查询条件\\";\\r\\n            LoadingDataFailedMsg = \\"取得数据失败\\";\\r\\n        }\\r\\n\\r\\n        pbcInit();\\r\\n    });\\r\\n\\r\\n    function pbcInit(){\\r\\n        var locale = document.getElementById('locale').value;\\r\\n        var url = \\"/cbweb-pbc-web/pbc/pbcInit?&locale=\\"+locale;\\r\\n\\r\\n        $.ajax({\\r\\n            type : \\"post\\",\\r\\n            url : url,\\r\\n            cache : false,\\r\\n            success : function(data) {\\r\\n                createGraph(data);\\r\\n            },\\r\\n            error : function() {\\r\\n                alert(LoadingDataFailedMsg);\\r\\n                $('#graph').html(\\"\\");\\r\\n                return;\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n\\r\\n    function createGraph(data){\\r\\n\\r\\n        if(data == null || data.length == 0){\\r\\n            alert(dataNullMsg);\\r\\n            $('#graph').html(\\"\\");\\r\\n            return;\\r\\n        }\\r\\n\\r\\n        var tempData;\\r\\n\\r\\n        options.series = new Array();\\r\\n        for(var i = 0; i < data.length; i++){\\r\\n            var yData = new Array();\\r\\n            options.series[i]=new Object();\\r\\n\\r\\n            tempData = data[i].seriesData;\\r\\n            for(var j = 0; j < tempData.length; j++){\\r\\n\\r\\n                var xValue = tempData[j][0];\\r\\n                if(xValue == 0){\\r\\n                    xData.push(zero);\\r\\n                }else if(xValue > 0 && xValue < 1){\\r\\n                    xData.push(xValue * 12 + month);\\r\\n                }else if(xValue >= 1){\\r\\n                    xData.push(xValue + year);\\r\\n                }else{\\r\\n                    xData.push(xValue);\\r\\n                }\\r\\n\\r\\n                var yValue;\\r\\n                if(xValue < 0.25){\\r\\n                    yValue = \\"\\";\\r\\n                }else{\\r\\n                    yValue = Number(tempData[j][1]);\\r\\n                }\\r\\n                if(xValue == 0.25 || xValue == 0.5 || xValue == 1 || xValue == 3\\r\\n                    || xValue == 5 || xValue == 7 || xValue == 10 || xValue == 30){\\r\\n                    yData.push({y:yValue,marker:{radius:2}});\\r\\n                }else{\\r\\n                    yData.push(yValue);\\r\\n                }\\r\\n                options.series[i].data = yData;\\r\\n                options.series[i].name = data[i].ycDefName;\\r\\n                options.series[i].color = colorArr[i];\\r\\n                options.series[i].dataGrouping = {enabled : false};\\r\\n                options.series[i].lineWidth = 1;\\r\\n            }\\r\\n\\r\\n        }\\r\\n\\r\\n        chart = new Highcharts.Chart(options);\\r\\n    }\\r\\n\\r\\n</script>\\r\\n</html>","headers":{"X-Xss-Protection":"1; mode=block","Date":"Wed, 23 Sep 2026 10:30:12 GMT","Set-Cookie":"JSESSIONID=F6FB6AACD5622F3BB09B9CC76D640F4E; Path=/cbweb-pbc-web; HttpOnly","Strict-Transport-Security":"max-age=30; includeSubDomains;","Connection":"keep-alive","X-Content-Type-Options":"nosniff","Vary":"Accept-Encoding","X-Frame-Options":"allowall","Content-Language":"und","Content-Type":"text/html;charset=UTF-8","Expect-Ct":"enforce; max-age=86400"},"status_code":200,"$startTime":1790159410946,"$endTime":1790159412337}	recvw2qrKGNzst
