ours();\\r\\n\\t\\t\\t\\tvar minute = now.getMinutes();\\r\\n\\t\\t\\t\\tvar second = now.getSeconds();\\r\\n\\t\\t\\t\\treturn PrefixInteger(date, 2) + \\"日 \\" + PrefixInteger(hour, 2) + \\"时\\"+PrefixInteger(minute, 2) + \\"分\\";;\\r\\n\\r\\n\\t\\t\\t}\\r\\n\\t\\t\\tfunction PrefixInteger(num, n) {\\r\\n\\t\\t\\t\\treturn(Array(n).join(0) + num).slice(-n);\\r\\n\\t\\t\\t}\\r\\n\\r\\nwindow.addEventListener('message',function(rs){\\r\\n    var pointdata=rs.data;\\r\\nif(pointdata=='refresh'){\\r\\n     window.location.reload();\\r\\n}else{\\r\\nconsole.log(pointdata);\\r\\n}\\r\\n})\\r\\n</script>\\r\\n\\t</body>\\r\\n\\r\\n</html>\\r\\n","headers":{"X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Thu, 01 Oct 2026 10:30:16 GMT","Server":"nginx","Set-Cookie":"WJSESSIONID=E72FF239009E7BEA6038A9C5297F0A91; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.239; local=123.58.10.239:48810; remote=219.140.196.72:80"},"status_code":200,"$startTime":1790850607171,"$endTime":1790850608263}	reczz28I77BMRc2m
