5mi96q7yfaj	5mi96q7yfaj	{"parentId":"97ta6u9ba34","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_bs_item"}},"__flowSurfaceMeta":{"declaredKey":"经营资产与负债（编辑）.main"},"cardSettings":{"titleDescription":{"description":"① 功能定位：资产负债表逐科目归类与重估（全公司口径）：经营资产与经营负债＝经营资本（第一层），其余＝资产负债桥（独立资产与调整）。\\n② 数据库基本表：vi_bs_item_base（页面上新增、修改都写回这里）\\n③ 这张表格引用了哪些表格：\\n　「假设依据」列 → 预测与估值 / 假设依据\\n　「截至日」「账面金额（亿元）」「重估金额（亿元）」「账面计入值（亿元）」「重估计入值（亿元）」「用途」列（自动）← 预测与估值 / ① 资产价值 / 资产价值口径（编辑）、预测与估值 / ⑤ 股权价值、经营与财务 / 财务报表（报表原值）\\n④ 哪些表格引用了这张表格：无"}},"tableSettings":{"pageSize":{"pageSize":50},"tableDensity":{"size":"middle"},"defaultSorting":{"sort":[{"field":"sort","direction":"asc"},{"field":"id","direction":"asc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"company_id","operator":"$eq","value":11},{"path":"category","operator":"$in","value":["经营资产","经营负债"]}]}}}}}
