aemeg6elgcd	aemeg6elgcd	{"parentId":"rfq81y5qauy","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{},"stepParams":{"jsSettings":{"runJs":{"version":"v1","code":"const {React,antd}=ctx.libs;\\nconst {Table, Typography, Card, Space, Alert, Statistic, Row, Col, Tag, theme}=antd;\\nconst {Text,Link}=Typography;\\nconst known=x=>x!==null && x!==undefined && x!=='' && Number.isFinite(Number(x));\\nconst fmt=x=>known(x)?Number(x).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';\\nconst total=(rows,key)=>rows.every(r=>known(r[key]))?rows.reduce((s,r)=>s+Number(r[key]),0):null;\\nasync function list(name, filter) {\\n  const res=ctx.makeResource('MultiRecordResource');\\n  res.setResourceName(name); res.setFilter(filter); res.setPageSize(300);\\n  await res.refresh(); return res.getData() || [];\\n}\\nasync function load() {\\n  const [co]=await list('vi_company',{code:{$eq:'01698.HK'}});\\n  const scope={company_id:{$eq:co.id}};\\n  const [raw,items,values,checks]=await Promise.all([\\n    list('vi_fin_stmt',{...scope,period_end:{$eq:co.as_of},stmt:{$eq:'资产负债表'}}),\\n    list('vi_bs_item',scope), list('vi_gw_value',scope), list('vi_check',scope)]);\\n  return {co,raw:raw.sort((a,b)=>a.seq-b.seq),items,v:values[0],checks};\\n}\\nconst controls=new Set(['非流动资产合计','流动资产合计','总资产','流动负债合计','净流动资产','总资产减流动负债','非流动负债合计','总负债','净资产','股东权益','总权益','总权益及非流动负债','总权益及总负债']);\\nconst equity=new Set(['股本','保留溢利(累计亏损)','公积金','其他储备','库存股']);\\nconst cashItems=new Set(['现金及等价物','短期存款','中长期存款','短期投资']);\\nconst marks={\\n  pool:{label:'现金合并后拆分',color:'purple'},\\n  split:{label:'分层计入',color:'purple'},\\n  keep:{label:'原值保留',color:'green'},\\n  transfer:{label:'原值列入第四层',color:'blue'},\\n  adjust:{label:'折价或调额',color:'orange'},\\n  check:{label:'核对',color:'default'},\\n  pending:{label:'待归类',color:'red'},\\n};\\nfunction treatment(row) {\\n  const m=row.model;\\n  if (!m) return row.category==='待归类'?'pending':'check';\\n  if (row.pool) return 'pool';\\n  if (row.split) return 'split';\\n  if (Number(m.haircut) || Number(m.adjustment)) return 'adjust';\\n  return m.role==='资产负债桥'?'transfer':'keep';\\n}\\nfunction badge(kind) {\\n  return <Tag color={marks[kind].color} style={{marginInlineEnd:0}}>{marks[kind].label}</Tag>;\\n}\\nfunction Page({d}) {\\n  const {token}=theme.useToken();\\n  const tints={pool:token.colorPrimaryBg,split:token.colorPrimaryBg,keep:token.colorSuccessBg,transfer:token.colorInfoBg,adjust:token.colorWarningBg,pending:token.colorErrorBg};\\n  const {raw,items,v,co,checks}=d;\\n  if (!raw.length || !v) return <Alert type=\\"warning\\" message=\\"本期资产负债表或重估结果待补。\\"/>;\\n  const amount=name=>raw.find(r=>r.item===name)?.amount;\\n  const mapped=new Map(items.filter(i=>i.line_item).map(i=>[i.line_item,i]));\\n  const reserve=items.find(i=>i.name==='经营所需现金（从现金划入）');\\n  const cashOut=items.find(i=>i.name==='划给经营的周转现金');\\n  const cashRows=items.filter(i=>cashItems.has(i.line_item));\\n  const grossCash=cashRows.length===cashItems.size?total(cashRows,'book_signed'):null;\\n  const independentCash=cashOut && cashRows.length===cashItems.size?total([...cashRows,cashOut],'value_signed'):null;\\n  const cashSplit=known(reserve?.value_signed) && Number(reserve.value_signed)>0 && known(cashOut?.value_signed);\\n  const splitPayable=items.some(i=>i.name==='投资应付款（从其他应付款划出）' && Number(i.value_signed)!==0);\\n  const rows=raw.map(r=>({...r,pool:cashSplit && cashItems.has(r.item),split:splitPayable && r.item==='其他应付款及应计费用',model:mapped.get(r.item),category:mapped.get(r.item)?.category ??\\n    (controls.has(r.item)?'报表合计':equity.has(r.item)?'权益核对':'待归类')}));\\n  const extra=items.filter(i=>!i.line_item || !raw.some(r=>r.item===i.line_item)).sort((a,b)=>a.sort-b.sort)\\n    .map(i=>({id:'extra'+i.id,item:i.name||i.line_item,category:i.category,model:i}));\\n  function shortNote(r) {\\n    const m=r.model;\\n    if (!m) return '';\\n    if (r.item==='商誉' && Number(m.haircut)===1) return '收购溢价难以单独变现，估值计零。';\\n    if (['指定以公允价值记账之金融资产','其他投资'].includes(r.item) && known(m.haircut))\\n      return '考虑处置税费和流动性，按账面值的'+Number(((1-m.haircut)*100).toFixed(1))+'%计入。';\\n    if (r.split) return '投资应付款单列，其余留作经营负债。';\\n    if (m.id===reserve?.id) return m.basis ? m.basis.split('。')[0]+'。' : '';\\n    if (m.id===cashOut?.id) return '周转金划回经营层，余额计入第四层。';\\n    if (r.item==='现金及等价物' && r.pool) return '与存款、短期投资合并后留出周转金。';\\n    if (r.item==='少数股东权益') return '经营部分已按归母比例折算，仅扣非经营部分。';\\n    if (r.item==='投资应付款（从其他应付款划出）') return '收购投资的待付价款，在第四层扣除。';\\n    if (r.item==='境内资金汇出预提税（10%）') return '按境内利润汇出时预计承担的税款扣减。';\\n    return '';\\n  }\\n  const cols=[\\n    {title:'科目及估值依据',dataIndex:'item',align:'left',width:280,\\n      render:(name,r)=>{\\n        const note=shortNote(r);\\n        return <div><span>{name}</span>{note && <div style={{marginTop:3,color:token.colorTextSecondary,fontSize:13,lineHeight:1.5}}>{note}</div>}</div>;\\n      }},\\n    {title:'性质',dataIndex:'category',align:'center',width:106},\\n    {title:'处理',key:'treatment',align:'center',width:132,render:(_,r)=>badge(treatment(r))},\\n    {title:'报表原值',dataIndex:'amount',align:'right',width:102,render:fmt},\\n    {title:'折价率',align:'right',width:76,render:(_,r)=>known(r.model?.haircut)?(100*r.model.haircut).toFixed(0)+'%':'—'},\\n    {title:'调整额¹',align:'right',width:90,render:(_,r)=>fmt(r.model?.adjustment)},\\n    {title:'① 经营计入',align:'right',width:106,render:(_,r)=>fmt(r.model?.role==='经营资本'?r.model.value_signed:null)},\\n    {title:'④ 独立计入',align:'right',width:106,render:(_,r)=>fmt(r.model?.role==='资产负债桥'?r.model.value_signed:null)},\\n  ];\\n  const table=data=><Table size=\\"small\\" rowKey=\\"id\\" pagination={false} tableLayout=\\"fixed\\" scroll={{x:1030}}\\n    onRow={r=>({style:{backgroundColor:tints[treatment(r)]}})} dataSource={data} columns={cols}\\n    expandable={{columnWidth:32,rowExpandable:r=>Boolean(r.model?.basis),expandedRowRender:r=>\\n      <div style={{maxWidth:'76ch',margin:'6px 20px',lineHeight:1.8}}>\\n        <Text strong>测算依据</Text>\\n        {r.model.basis.split('。').filter(Boolean).map((part,i)=><div key={i}>{part}。</div>)}\\n      </div>}}/>;\\n  const ops=items.filter(i=>i.role==='经营资本');\\n  const signedBook=total(ops,'book_signed');\\n  const toOperating=ops.reduce((s,i)=>s+(i.category==='经营负债'?-1:1)*Number(i.adjustment??0),0);\\n  const beforeHaircuts=known(signedBook)?signedBook+toOperating:null;\\n  const investments=total(items.filter(i=>i.category==='现金与投资'),'book_signed');\\n  const debt=total(items.filter(i=>i.category==='有息负债'),'book_signed');\\n  const reconciles=[amount('净资产'),investments,debt,signedBook].every(known) &&\\n    Math.abs(Number(amount('净资产'))-investments-debt-signedBook)<0.011;\\n  const metrics=[['总资产',amount('总资产')],['总负债',amount('总负债')],['合并净资产',amount('净资产')],['第一层归母价值',v.av_total]];\\n  return <Space direction=\\"vertical\\" size=\\"middle\\" style={{width:'100%',maxWidth:1240,marginInline:'auto',display:'flex',fontVariantNumeric:'tabular-nums'}}>\\n    <Card size=\\"small\\" title={'资产负债表 → 经营资产价值 · '+String(co.as_of).slice(0,10)+'（亿元）'}>\\n      <Row gutter={[16,12]} style={{textAlign:'center'}}>{metrics.map(([title,value])=><Col key={title} xs={12} md={6}><Statistic title={title} value={fmt(value)}/></Col>)}</Row>\\n      <p>合并净资产 {fmt(amount('净资产'))} − 现金与投资账面额 {fmt(investments)} ＋ 有息负债 {fmt(known(debt)?-debt:null)} ＝ 账面经营资本 {fmt(signedBook)}。</p>\\n      <div>经营项目调整 {fmt(toOperating)} 后为 {fmt(beforeHaircuts)}，再扣逐项折价 {fmt(known(beforeHaircuts) && known(v.adj_capital)?beforeHaircuts-v.adj_capital:null)}，得到经营净资产 <b>{fmt(v.adj_capital)}</b>。按当前口径「{v.av_basis}」及归母比例 {known(v.av_attrib)?(v.av_attrib*100).toFixed(1)+'%':'—'} 计入第一层。</div>\\n    </Card>\\n    {(!reconciles || rows.some(r=>r.category==='待归类')) && <Alert type=\\"warning\\" message=\\"有报表科目待归类或账面经营资本尚未对平，请复核下表。\\"/>}\\n    {cashSplit && <Card size=\\"small\\" title=\\"现金如何分到两层（亿元）\\">\\n      <Row gutter={[16,12]} style={{textAlign:'center'}}>{[['现金、存款与短期投资',grossCash],['① 经营周转',reserve.value_signed],['④ 剩余现金',independentCash]].map(([title,value])=><Col xs={24} md={8} key={title}><Statistic title={title} value={fmt(value)}/></Col>)}</Row>\\n      {reserve.basis && <div style={{marginTop:10}}><strong>{reserve.basis.split('。')[0]}。</strong>\\n        <details><summary style={{cursor:'pointer'}}>查看三项测算与压力假设</summary>\\n          {reserve.basis.split('。').slice(1).filter(Boolean).map((line,i)=><p key={i} style={{margin:'6px 0'}}>{line}。</p>)}\\n        </details></div>}\\n    </Card>}\\n    <Card size=\\"small\\" title=\\"逐项归类与折价（亿元）\\">\\n      <Text type=\\"secondary\\">按原表行次排列。原值沿用报表符号，两列计入值按资产为正、负债为负。合计和权益核对行不重复加总。</Text>\\n      <div style={{margin:'8px 0 12px'}}><Space wrap size={8}>{badge('keep')}{badge('transfer')}{badge('split')}{badge('adjust')}{badge('check')}</Space></div>\\n      {table(rows)}\\n      <h4>跨层划转与其他估值调整</h4>{table(extra)}\\n      <Text type=\\"secondary\\">¹ 调整额按科目自身方向填写。例如应付款调减，经营负债的扣除额随之减少。</Text>\\n    </Card>\\n    <Link href=\\"/admin/midgc6nurls\\">④ 独立资产与负债明细 · 净额 {fmt(v.bridge)} 亿元</Link>\\n    <details><summary>模型检查</summary>{checks.filter(c=>['G01','G07'].includes(c.code)).map(c=><p key={c.code}>{c.name} · {c.result}　{c.detail}</p>)}</details>\\n  </Space>;\\n}\\nfunction App(){\\n  const [data,setData]=React.useState(null),[error,setError]=React.useState('');\\n  React.useEffect(()=>{load().then(setData).catch(e=>setError(String(e)));},[]);\\n  if(error)return <Alert type=\\"error\\" message={error}/>;\\n  return data?<Page d={data}/>:<Text>正在读取资产负债表…</Text>;\\n}\\nctx.render(<App/>);\\n"}},"__flowSurfaceMeta":{"declaredKey":"总览.jsBlock_1"}}}
