yyion2z2t3t	yyion2z2t3t	{"parentId":"3on5qhuvsng","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_company"}},"__flowSurfaceMeta":{"declaredKey":"资产价值口径（编辑）.main"},"cardSettings":{"titleDescription":{"description":"① 功能定位：研究的公司：股价取数、业务量口径与估值设置（截至日、股本、主估值层）。\\n② 数据库基本表：vi_company_base（页面上新增、修改都写回这里）\\n③ 这张表格引用了哪些表格：\\n　「股价指标」列 → 经营与财务 / 定量指标\\n　「股价汇率指标」列 → 经营与财务 / 定量指标\\n　「订阅的宏观数据」列 → 经营与财务 / 定量指标\\n　「最新股价（元）」「最新股价（原币）」「最新股价日期」「折算汇率」列（自动）← 经营与财务 / 定量指标\\n　「用到的宏观数据」列（自动）← 经营与财务 / 定量指标、预测与估值 / 假设依据、商业模式 / 风险分析\\n④ 哪些表格引用了这张表格：所有研究表格都有「公司」列，记录按公司归属到这里（不逐一列出）"}},"tableSettings":{"pageSize":{"pageSize":50},"tableDensity":{"size":"middle"},"defaultSorting":{"sort":[{"field":"id","direction":"asc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"id","operator":"$eq","value":11}]}}}}}
