6rx7hpwhqls	6rx7hpwhqls	{"use":"DetailsGridModel","subKey":"grid","subType":"object","stepParams":{"__flowSurfaceMeta":{"declaredKey":"资产负债桥（编辑）.main.judgments.popup.details_1.grid"},"gridSettings":{"grid":{"rows":{"row1":[["0g3qlhiykum"],["koa8k4o8rkx"]],"row2":[["f82kubyw1i5"],["r4qvyq1mzuj"]],"row3":[["g1g4x9i38of"],["wn8flhl1v4f"]]},"sizes":{"row1":[12,12],"row2":[12,12],"row3":[12,12]},"rowOrder":["row1","row2","row3"]}}},"props":{"rows":{"row1":[["0g3qlhiykum"],["koa8k4o8rkx"]],"row2":[["f82kubyw1i5"],["r4qvyq1mzuj"]],"row3":[["g1g4x9i38of"],["wn8flhl1v4f"]]},"sizes":{"row1":[12,12],"row2":[12,12],"row3":[12,12]},"rowOrder":["row1","row2","row3"]}}
