2rwgy8d0pzs	2rwgy8d0pzs	{"use":"DetailsGridModel","subKey":"grid","subType":"object","stepParams":{"gridSettings":{"grid":{"rows":{"row1":[["qhjtie9o6ak"],["j6z8a25xzt8"]],"row2":[["tkfuly0gcr5"],["6p8oi8f3m21"]],"row3":[["4w1alizw8xn"],["dg9qasqf9ng"]],"row4":[["u2vc2cprn48"],["tdmnqm8edkn"]],"row5":[["kqmqeeu5gnr"]]},"sizes":{"row1":[12,12],"row2":[12,12],"row3":[12,12],"row4":[12,12],"row5":[24]},"rowOrder":["row1","row2","row3","row4","row5"]}}},"props":{"rows":{"row1":[["t1b1ah8ozxu"],["p6riqpjcoc6"]],"row2":[["3r4gs3bs1wd"],["10ui2pysvho"]],"row3":[["zcmzp2nrynw"],["paz7h1ftjsm"]],"row4":[["q3ick5h6doe"],["splppnqmohj"]],"row5":[["nuunziuft0s"]]},"sizes":{"row1":[12,12],"row2":[12,12],"row3":[12,12],"row4":[12,12],"row5":[24]},"rowOrder":["row1","row2","row3","row4","row5"]},"parent":"iu9588uavld","parentId":"iu9588uavld","sortIndex":1}
