: 'value', name: spec.unit, scale: spec.scale || false, splitLine: {lineStyle: {color: '#edf0f4'}}},\\n  dataZoom: zoom ? [{type: 'inside'}, {type: 'slider', height: 18, bottom: 8, showDetail: false}] : [],\\n  series: names.map((name, i) => ({name, type: spec.kind, barMaxWidth: 30,\\n    showSymbol: categories.length < 25, symbolSize: 5, connectNulls: false,\\n    itemStyle: {color: fixedColors[name] || colors[i % colors.length]},\\n    lineStyle: {width: 2, type: /市场价|要求收益率/.test(name) ? 'dashed' : 'solid'},\\n    data: categories.map((category) => {\\n      const row = rows.find((r) => String(r[spec.x]) === category && (!spec.group || String(r[spec.group]) === name));\\n      return row && row[spec.y] !== null && row[spec.y] !== undefined ? Number(row[spec.y]) : null;\\n    }),\\n  })),\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.price"},"cardSettings":{"titleDescription":{"title":"A 股收盘价（元/股，不复权）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
trp1apyq07d	trp1apyq07d	{"parentId":"s6kdrmqmncp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT f.dimension AS \\"维度\\", f.score AS \\"评分\\" FROM vi_fit_score_base f JOIN vi_company_base co ON co.id = f.company_id AND co.code = '600900.SH' ORDER BY f.sort, f.id"},"chart":{"option":{"mode":"custom","raw":"const rows = ctx.data?.objects || [];\\nreturn {\\n  animation: false,\\n  grid: { left: 12, right: 30, top: 16, bottom: 12, containLabel: true },\\n  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },\\n  xAxis: { type: 'value', min: 0, max: 5, interval: 1, splitLine: { lineStyle: { color: '#edf0f4' } } },\\n  yAxis: { type: 'category', inverse: true, data: rows.map((row) => row['维度']), axisTick: { show: false } },\\n  series: [{ name: '评分', type: 'bar', barMaxWidth: 22, itemStyle: { color: '#5470c6' },\\n    label: { show: true, position: 'right' }, data: rows.map((row) => Number(row['评分'])) }],\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.fit"},"cardSettings":{"titleDescription":{"title":"价值投资适配度（各项 0—5 分）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
