hb1d8e5h1qx	hb1d8e5h1qx	{"parentId":"4a1gc3m24y4","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT d.period, round(d.value::numeric, 1) AS \\"减值\\" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '601668.SH' WHERE d.line_item = '资产及信用减值损失' AND d.period_kind = '全年' AND d.period >= '2019' ORDER BY d.period_end"},"chart":{"option":{"mode":"custom","raw":"const spec = {\\"x\\": \\"period\\", \\"y\\": \\"减值\\", \\"group\\": null, \\"label\\": \\"年度资产及信用减值损失\\", \\"kind\\": \\"bar\\", \\"unit\\": \\"亿元\\", \\"labels\\": {\\"手机×AIoT 分部收入\\": \\"手机×AIoT\\", \\"智能电动汽车及AI分部收入\\": \\"汽车及 AI\\", \\"生态经营利润（推算）\\": \\"手机×AIoT（推算）\\", \\"汽车及AI分部经营损益\\": \\"汽车及 AI（含 AI 投入）\\", \\"智能手机毛利率\\": \\"手机\\", \\"IoT毛利率\\": \\"IoT\\", \\"互联网服务毛利率\\": \\"互联网\\", \\"汽车及AI分部毛利率\\": \\"汽车及 AI\\"}, \\"scale\\": false};\\nconst rows = (ctx.data?.objects || []).map((r) => ({...r, [spec.group]: spec.labels?.[r[spec.group]] || r[spec.group]}));\\nconst categories = [...new Set(rows.map((r) => String(r[spec.x])))];\\nconst names = [...new Set(rows.map((r) => spec.group ? String(r[spec.group]) : spec.label))];\\nconst colors = ['#5470c6', '#2b9d8f', '#d99044', '#66758a', '#9b72b0'];\\nconst fixedColors = {'隐含收益率': '#5470c6', '现金支持口径': '#2b9d8f', '要求收益率': '#66758a', '悲观': '#d99044', '基准': '#5470c6', '乐观': '#2b9d8f', '市场价': '#66758a'};\\nconst zoom = categories.length > 45;\\nreturn {\\n  animation: false,\\n  grid: {left: 12, right: 22, top: 48, bottom: zoom ? 54 : 18, containLabel: true},\\n  legend: {top: 0, type: 'scroll', textStyle: {fontSize: 11}},\\n  tooltip: {trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toLocaleString('zh-CN', {maximumFractionDigits: spec.digits ?? 2})} ${spec.unit}`},\\n  xAxis: {type: 'category', data: categories, boundaryGap: spec.kind === 'bar',\\n    axisLabel: {hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v}, axisTick: {alignWithLabel: true}},\\n  yAxis: {type: 'value', name: spec.unit, scale: spec.scale || false, splitLine: {lineStyle: {color: '#edf0f4'}}},\\n  dataZoom: zoom ? [{type: 'inside'}, {type: 'slider', height: 18, bottom: 8, showDetail: false}] : [],\\n  series: names.map((name, i) => ({name, type: spec.kind, barMaxWidth: 30,\\n    showSymbol: categories.length < 25, symbolSize: 5, connectNulls: false,\\n    itemStyle: {color: fixedColors[name] || colors[i % colors.length]},\\n    lineStyle: {width: 2, type: /市场价|要求收益率/.test(name) ? 'dashed' : 'solid'},\\n    data: categories.map((category) => {\\n      const row = rows.find((r) => String(r[spec.x]) === category && (!spec.group || String(r[spec.group]) === name));\\n      return row && row[spec.y] !== null && row[spec.y] !== undefined ? Number(row[spec.y]) : null;\\n    }),\\n  })),\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.imp"},"cardSettings":{"titleDescription":{"title":"年度资产及信用减值损失（亿元）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
euxyu7zb039	euxyu7zb039	{"parentId":"4a1gc3m24y4","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT s.period, CASE m.name WHEN '归母ROE（同业口径）' THEN '中国建筑' ELSE '六家建筑央企中位数' END AS \\"口径\\", round(s.value::numeric, 2) AS \\"数值（%）\\" FROM vi_series s JOIN vi_metric_base m ON m.id = s.metric_id AND m.company_id = (SELECT id FROM vi_company_base WHERE code = '601668.SH') AND m.name IN ('归母ROE（同业口径）', '同业ROE中位数（六家建筑央企）') WHERE s.basis = '全年' ORDER BY s.period, 2"},"chart":{"option":{"mode":"custom","raw":"const spec = {\\"x\\": \\"period\\", \\"y\\": \\"数值（%）\\", \\"group\\": \\"口径\\", \\"label\\": \\"ROE：中国建筑 vs 六家建筑央企中位数\\", \\"kind\\": \\"line\\", \\"unit\\": \\"%\\", \\"labels\\": {\\"手机×AIoT 分部收入\\": \\"手机×AIoT\\", \\"智能电动汽车及AI分部收入\\": \\"汽车及 AI\\", \\"生态经营利润（推算）\\": \\"手机×AIoT（推算）\\", \\"汽车及AI分部经营损益\\": \\"汽车及 AI（含 AI 投入）\\", \\"智能手机毛利率\\": \\"手机\\", \\"IoT毛利率\\": \\"IoT\\", \\"互联网服务毛利率\\": \\"互联网\\", \\"汽车及AI分部毛利率\\": \\"汽车及 AI\\"}, \\"scale\\": false};\\nconst rows = (ctx.data?.objects || []).map((r) => ({...r, [spec.group]: spec.labels?.[r[spec.group]] || r[spec.group]}));\\nconst categories = [...new Set(rows.map((r) => String(r[spec.x])))];\\nconst names = [...new Set(rows.map((r) => spec.group ? String(r[spec.group]) : spec.label))];\\nconst colors = ['#5470c6', '#2b9d8f', '#d99044', '#66758a', '#9b72b0'];\\nconst fixedColors = {'隐含收益率': '#5470c6', '现金支持口径': '#2b9d8f', '要求收益率': '#66758a', '悲观': '#d99044', '基准': '#5470c6', '乐观': '#2b9d8f', '市场价': '#66758a'};\\nconst zoom = categories.length > 45;\\nreturn {\\n  animation: false,\\n  grid: {left: 12, right: 22, top: 48, bottom: zoom ? 54 : 18, containLabel: true},\\n  legend: {top: 0, type: 'scroll', textStyle: {fontSize: 11}},\\n  tooltip: {trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toLocaleString('zh-CN', {maximumFractionDigits: spec.digits ?? 2})} ${spec.unit}`},\\n  xAxis: {type: 'category', data: categories, boundaryGap: spec.kind === 'bar',\\n    axisLabel: {hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v}, axisTick: {alignWithLabel: true}},\\n  yAxis: {type: 'value', name: spec.unit, scale: spec.scale || false, splitLine: {lineStyle: {color: '#edf0f4'}}},\\n  dataZoom: zoom ? [{type: 'inside'}, {type: 'slider', height: 18, bottom: 8, showDetail: false}] : [],\\n  series: names.map((name, i) => ({name, type: spec.kind, barMaxWidth: 30,\\n    showSymbol: categories.length < 25, symbolSize: 5, connectNulls: false,\\n    itemStyle: {color: fixedColors[name] || colors[i % colors.length]},\\n    lineStyle: {width: 2, type: /市场价|要求收益率/.test(name) ? 'dashed' : 'solid'},\\n    data: categories.map((category) => {\\n      const row = rows.find((r) => String(r[spec.x]) === category && (!spec.group || String(r[spec.group]) === name));\\n      return row && row[spec.y] !== null && row[spec.y] !== undefined ? Number(row[spec.y]) : null;\\n    }),\\n  })),\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.peer_roe"},"cardSettings":{"titleDescription":{"title":"ROE：中国建筑 vs 六家建筑央企中位数（%）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
