fb5qx1sri6b	fb5qx1sri6b	{"parentId":"1a709wnr8ab","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT d.period, CASE d.line_item WHEN '会员（订阅）收入' THEN '会员订阅' WHEN '非订阅音乐收入（广告、演出、周边）' THEN '非订阅音乐' ELSE '社交娱乐' END AS 项目,d.value AS 亿元 FROM vi_disclosed d JOIN vi_company_base co ON co.id=d.company_id AND co.code='01698.HK' WHERE d.period_kind='单季' AND d.line_item IN ('会员（订阅）收入','非订阅音乐收入（广告、演出、周边）','社交娱乐及其他收入') ORDER BY d.period_end,2"},"chart":{"option":{"mode":"custom","raw":"const rows = ctx.data?.objects || [];\\nconst spec = {\\"x\\": \\"period\\", \\"y\\": \\"亿元\\", \\"group\\": \\"项目\\", \\"kind\\": \\"bar\\", \\"unit\\": \\"亿元\\", \\"stack\\": true, \\"names\\": [\\"会员订阅\\", \\"非订阅音乐\\", \\"社交娱乐\\"]};\\nconst categories = [...new Set(rows.map((row) => String(row[spec.x])))];\\nconst names = spec.names || [...new Set(rows.map((row) => spec.group ? String(row[spec.group]) : spec.label))];\\nconst colors = spec.colors || ['#5470c6', '#2b9d8f', '#d99044', '#66758a'];\\nconst numeric = (value) => value === null || value === undefined ? null : Number(value);\\nconst series = names.map((name, index) => ({\\n  name,\\n  type: spec.kind,\\n  stack: spec.stack ? 'total' : undefined,\\n  barMaxWidth: 32,\\n  connectNulls: false,\\n  showSymbol: categories.length < 30,\\n  symbolSize: 5,\\n  lineStyle: { width: 2 },\\n  itemStyle: { color: colors[index % colors.length] },\\n  data: categories.map((category) => {\\n    const row = rows.find((item) => String(item[spec.x]) === category && (!spec.group || String(item[spec.group]) === name));\\n    return row ? numeric(row[spec.y]) : null;\\n  }),\\n}));\\nreturn {\\n  animation: false,\\n  grid: { left: 12, right: 22, top: 44, bottom: spec.note ? 42 : 16, containLabel: true },\\n  legend: { top: 0, type: 'scroll', textStyle: { fontSize: 12 } },\\n  tooltip: { trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toFixed(spec.digits ?? 1)} ${spec.unit}` },\\n  xAxis: {\\n    type: 'category',\\n    data: categories,\\n    boundaryGap: spec.kind === 'bar',\\n    axisLabel: { hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v },\\n    axisTick: { alignWithLabel: true },\\n  },\\n  yAxis: { type: 'value', min: spec.min, max: spec.max, name: spec.unit, splitLine: { lineStyle: { color: '#edf0f4' } } },\\n  graphic: spec.note ? [{ type: 'text', left: 'center', bottom: 0, style: { text: spec.note, fill: '#8c8c8c', fontSize: 11 } }] : [],\\n  series,\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.rev_mix"},"cardSettings":{"titleDescription":{"title":"单季收入结构（亿元）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
zfkqsnotn3n	zfkqsnotn3n	{"parentId":"1a709wnr8ab","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT d.period, CASE d.line_item WHEN '会员（订阅）收入' THEN '会员订阅' WHEN '社交娱乐及其他收入' THEN '社交娱乐' ELSE d.line_item END AS \\"项目\\", round((d.yoy * 100)::numeric, 1) AS \\"同比（%）\\" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period_kind = '单季' AND d.yoy IS NOT NULL AND d.period_end >= '2024-01-01' AND d.line_item IN ('会员（订阅）收入', '社交娱乐及其他收入', '营业收入') ORDER BY d.period_end, 2"},"chart":{"option":{"mode":"custom","raw":"const rows = ctx.data?.objects || [];\\nconst spec = {\\"x\\": \\"period\\", \\"y\\": \\"同比（%）\\", \\"group\\": \\"项目\\", \\"kind\\": \\"line\\", \\"unit\\": \\"%\\", \\"names\\": [\\"会员订阅\\", \\"社交娱乐\\", \\"营业收入\\"], \\"colors\\": [\\"#5470c6\\", \\"#d99044\\", \\"#66758a\\"]};\\nconst categories = [...new Set(rows.map((row) => String(row[spec.x])))];\\nconst names = spec.names || [...new Set(rows.map((row) => spec.group ? String(row[spec.group]) : spec.label))];\\nconst colors = spec.colors || ['#5470c6', '#2b9d8f', '#d99044', '#66758a'];\\nconst numeric = (value) => value === null || value === undefined ? null : Number(value);\\nconst series = names.map((name, index) => ({\\n  name,\\n  type: spec.kind,\\n  stack: spec.stack ? 'total' : undefined,\\n  barMaxWidth: 32,\\n  connectNulls: false,\\n  showSymbol: categories.length < 30,\\n  symbolSize: 5,\\n  lineStyle: { width: 2 },\\n  itemStyle: { color: colors[index % colors.length] },\\n  data: categories.map((category) => {\\n    const row = rows.find((item) => String(item[spec.x]) === category && (!spec.group || String(item[spec.group]) === name));\\n    return row ? numeric(row[spec.y]) : null;\\n  }),\\n}));\\nreturn {\\n  animation: false,\\n  grid: { left: 12, right: 22, top: 44, bottom: spec.note ? 42 : 16, containLabel: true },\\n  legend: { top: 0, type: 'scroll', textStyle: { fontSize: 12 } },\\n  tooltip: { trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toFixed(spec.digits ?? 1)} ${spec.unit}` },\\n  xAxis: {\\n    type: 'category',\\n    data: categories,\\n    boundaryGap: spec.kind === 'bar',\\n    axisLabel: { hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v },\\n    axisTick: { alignWithLabel: true },\\n  },\\n  yAxis: { type: 'value', min: spec.min, max: spec.max, name: spec.unit, splitLine: { lineStyle: { color: '#edf0f4' } } },\\n  graphic: spec.note ? [{ type: 'text', left: 'center', bottom: 0, style: { text: spec.note, fill: '#8c8c8c', fontSize: 11 } }] : [],\\n  series,\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.sub_yoy"},"cardSettings":{"titleDescription":{"title":"单季收入同比（%）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
