5uvl8l5e4zp	5uvl8l5e4zp	{"parentId":"1a709wnr8ab","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT d.period, d.line_item AS \\"项目\\", d.value AS \\"百万人\\" FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period_kind='时点' AND d.period ~ 'Q[1-4]$' AND d.period >= '2024Q1' AND d.line_item IN ('在线音乐月活跃用户', '在线音乐付费用户') ORDER BY d.period_end, 2"},"chart":{"option":{"mode":"custom","raw":"const rows = ctx.data?.objects || [];\\nconst spec = {\\"x\\": \\"period\\", \\"y\\": \\"百万人\\", \\"group\\": \\"项目\\", \\"kind\\": \\"line\\", \\"unit\\": \\"百万人\\", \\"names\\": [\\"在线音乐付费用户\\", \\"在线音乐月活跃用户\\"], \\"note\\": \\"2026 年起停止季度披露；此处仅比较同口径季末数据\\"};\\nconst categories = [...new Set(rows.map((row) => String(row[spec.x])))];\\nconst names = spec.names || [...new Set(rows.map((row) => spec.group ? String(row[spec.group]) : spec.label))];\\nconst colors = spec.colors || ['#5470c6', '#2b9d8f', '#d99044', '#66758a'];\\nconst numeric = (value) => value === null || value === undefined ? null : Number(value);\\nconst series = names.map((name, index) => ({\\n  name,\\n  type: spec.kind,\\n  stack: spec.stack ? 'total' : undefined,\\n  barMaxWidth: 32,\\n  connectNulls: false,\\n  showSymbol: categories.length < 30,\\n  symbolSize: 5,\\n  lineStyle: { width: 2 },\\n  itemStyle: { color: colors[index % colors.length] },\\n  data: categories.map((category) => {\\n    const row = rows.find((item) => String(item[spec.x]) === category && (!spec.group || String(item[spec.group]) === name));\\n    return row ? numeric(row[spec.y]) : null;\\n  }),\\n}));\\nreturn {\\n  animation: false,\\n  grid: { left: 12, right: 22, top: 44, bottom: spec.note ? 42 : 16, containLabel: true },\\n  legend: { top: 0, type: 'scroll', textStyle: { fontSize: 12 } },\\n  tooltip: { trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toFixed(spec.digits ?? 1)} ${spec.unit}` },\\n  xAxis: {\\n    type: 'category',\\n    data: categories,\\n    boundaryGap: spec.kind === 'bar',\\n    axisLabel: { hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v },\\n    axisTick: { alignWithLabel: true },\\n  },\\n  yAxis: { type: 'value', min: spec.min, max: spec.max, name: spec.unit, splitLine: { lineStyle: { color: '#edf0f4' } } },\\n  graphic: spec.note ? [{ type: 'text', left: 'center', bottom: 0, style: { text: spec.note, fill: '#8c8c8c', fontSize: 11 } }] : [],\\n  series,\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.users"},"cardSettings":{"titleDescription":{"title":"在线音乐用户（百万人，季末披露）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
j8ir6vc4ovf	j8ir6vc4ovf	{"parentId":"7t4t6fn4gmc","subKey":"items","subType":"array","use":"DividerItemModel","props":{"label":"基本信息（1/2）","orientation":"left"},"decoratorProps":{},"stepParams":{"__flowSurfaceMeta":{"declaredKey":"定期经营.disclosed.edit_2.popup.editForm_1.1_2_divider"},"markdownItemSetting":{"title":{"label":"基本信息（1/2）","orientation":"left"}}}}
jroiw1a93uu	jroiw1a93uu	{"parentId":"1a709wnr8ab","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year, x.item, x.amount FROM vi_fin_history h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item"},"chart":{"option":{"mode":"custom","raw":"const rows = ctx.data?.objects || [];\\nconst spec = {\\"x\\": \\"year\\", \\"y\\": \\"amount\\", \\"group\\": \\"item\\", \\"kind\\": \\"bar\\", \\"unit\\": \\"亿元\\", \\"names\\": [\\"经营现金流\\", \\"资本开支\\"]};\\nconst categories = [...new Set(rows.map((row) => String(row[spec.x])))];\\nconst names = spec.names || [...new Set(rows.map((row) => spec.group ? String(row[spec.group]) : spec.label))];\\nconst colors = spec.colors || ['#5470c6', '#2b9d8f', '#d99044', '#66758a'];\\nconst numeric = (value) => value === null || value === undefined ? null : Number(value);\\nconst series = names.map((name, index) => ({\\n  name,\\n  type: spec.kind,\\n  stack: spec.stack ? 'total' : undefined,\\n  barMaxWidth: 32,\\n  connectNulls: false,\\n  showSymbol: categories.length < 30,\\n  symbolSize: 5,\\n  lineStyle: { width: 2 },\\n  itemStyle: { color: colors[index % colors.length] },\\n  data: categories.map((category) => {\\n    const row = rows.find((item) => String(item[spec.x]) === category && (!spec.group || String(item[spec.group]) === name));\\n    return row ? numeric(row[spec.y]) : null;\\n  }),\\n}));\\nreturn {\\n  animation: false,\\n  grid: { left: 12, right: 22, top: 44, bottom: spec.note ? 42 : 16, containLabel: true },\\n  legend: { top: 0, type: 'scroll', textStyle: { fontSize: 12 } },\\n  tooltip: { trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toFixed(spec.digits ?? 1)} ${spec.unit}` },\\n  xAxis: {\\n    type: 'category',\\n    data: categories,\\n    boundaryGap: spec.kind === 'bar',\\n    axisLabel: { hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v },\\n    axisTick: { alignWithLabel: true },\\n  },\\n  yAxis: { type: 'value', min: spec.min, max: spec.max, name: spec.unit, splitLine: { lineStyle: { color: '#edf0f4' } } },\\n  graphic: spec.note ? [{ type: 'text', left: 'center', bottom: 0, style: { text: spec.note, fill: '#8c8c8c', fontSize: 11 } }] : [],\\n  series,\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.hist_cash"},"cardSettings":{"titleDescription":{"title":"经营现金流与资本开支（亿元）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
