waywpf5iwx4	waywpf5iwx4	{"parentId":"ecz6csb8a9d","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year, x.item, x.amount FROM vi_fin_history h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01810.HK' CROSS JOIN LATERAL (VALUES ('经营现金流', h.cfo), ('资本开支', h.capex)) x(item, amount) WHERE x.amount IS NOT NULL ORDER BY h.year, x.item"},"chart":{"option":{"mode":"custom","raw":"const spec = {\\"x\\": \\"year\\", \\"y\\": \\"amount\\", \\"group\\": \\"item\\", \\"label\\": \\"经营现金流与资本开支\\", \\"kind\\": \\"bar\\", \\"unit\\": \\"亿元\\", \\"labels\\": {\\"手机×AIoT 分部收入\\": \\"手机×AIoT\\", \\"智能电动汽车及AI分部收入\\": \\"汽车及 AI\\", \\"生态经营利润（推算）\\": \\"手机×AIoT（推算）\\", \\"汽车及AI分部经营损益\\": \\"汽车及 AI（含 AI 投入）\\", \\"智能手机毛利率\\": \\"手机\\", \\"IoT毛利率\\": \\"IoT\\", \\"互联网服务毛利率\\": \\"互联网\\", \\"汽车及AI分部毛利率\\": \\"汽车及 AI\\"}, \\"scale\\": false};\\nconst rows = (ctx.data?.objects || []).map((r) => ({...r, [spec.group]: spec.labels?.[r[spec.group]] || r[spec.group]}));\\nconst categories = [...new Set(rows.map((r) => String(r[spec.x])))];\\nconst names = [...new Set(rows.map((r) => spec.group ? String(r[spec.group]) : spec.label))];\\nconst colors = ['#5470c6', '#2b9d8f', '#d99044', '#66758a', '#9b72b0'];\\nconst fixedColors = {'隐含收益率': '#5470c6', '现金支持口径': '#2b9d8f', '要求收益率': '#66758a', '悲观': '#d99044', '基准': '#5470c6', '乐观': '#2b9d8f', '市场价': '#66758a'};\\nconst zoom = categories.length > 45;\\nreturn {\\n  animation: false,\\n  grid: {left: 12, right: 22, top: 48, bottom: zoom ? 54 : 18, containLabel: true},\\n  legend: {top: 0, type: 'scroll', textStyle: {fontSize: 11}},\\n  tooltip: {trigger: 'axis', valueFormatter: (v) => v === null ? '—' : `${Number(v).toLocaleString('zh-CN', {maximumFractionDigits: spec.digits ?? 2})} ${spec.unit}`},\\n  xAxis: {type: 'category', data: categories, boundaryGap: spec.kind === 'bar',\\n    axisLabel: {hideOverlap: true, formatter: (v) => /^\\\\d{4}Q/.test(v) ? v.slice(2) : v}, axisTick: {alignWithLabel: true}},\\n  yAxis: {type: 'value', name: spec.unit, scale: spec.scale || false, splitLine: {lineStyle: {color: '#edf0f4'}}},\\n  dataZoom: zoom ? [{type: 'inside'}, {type: 'slider', height: 18, bottom: 8, showDetail: false}] : [],\\n  series: names.map((name, i) => ({name, type: spec.kind, barMaxWidth: 30,\\n    showSymbol: categories.length < 25, symbolSize: 5, connectNulls: false,\\n    itemStyle: {color: fixedColors[name] || colors[i % colors.length]},\\n    lineStyle: {width: 2, type: /市场价|要求收益率/.test(name) ? 'dashed' : 'solid'},\\n    data: categories.map((category) => {\\n      const row = rows.find((r) => String(r[spec.x]) === category && (!spec.group || String(r[spec.group]) === name));\\n      return row && row[spec.y] !== null && row[spec.y] !== undefined ? Number(row[spec.y]) : null;\\n    }),\\n  })),\\n};"}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.hist_cash"},"cardSettings":{"titleDescription":{"title":"经营现金流与资本开支（亿元）"},"blockHeight":{"heightMode":"specifyValue","height":360}}}}
0m460gitjjs	0m460gitjjs	{"parentId":"ecz6csb8a9d","subKey":"items","subType":"array","use":"JSBlockModel","props":{},"decoratorProps":{"title":"关键读数"},"stepParams":{"jsSettings":{"runJs":{"version":"v2","code":"// 现价与三层价值（资产价值、盈利能力价值、含增长价值）；isBase＝主估值层。只展示，不计算。\\nfunction PriceSummary({ price, scenarios, unit = '港元', date }) {\\n  const valid = (v) => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));\\n  const fmtPrice = (v) => valid(v) ? Number(v).toFixed(2) : '—';\\n  const palettes = { '资产价值': { ink: '#5b6472', bg: '#f4f5f7', border: '#d9dde3', icon: '▤', hint: '第一层' }, '盈利能力价值': { ink: '#1d4ed8', bg: '#edf4ff', border: '#7da8f5', icon: '◆', hint: '第二层' }, '含增长价值': { ink: '#1f7a4d', bg: '#eefaf3', border: '#b7e4c7', icon: '↗', hint: '第三层' } };\\n  const ordered = scenarios.slice();\\n  const base = ordered.find((s) => s.isBase);\\n  const gap = valid(price) && valid(base?.value) && Number(base.value) > 0 ? Number(price) / Number(base.value) - 1 : null;\\n  const points = ordered.filter((s) => valid(s.value));\\n  const prices = [...points.map((s) => Number(s.value)), ...(valid(price) ? [Number(price)] : [])];\\n  const lo = prices.length ? Math.min(...prices) * 0.85 : 0;\\n  const hi = prices.length ? Math.max(...prices) * 1.08 : 1;\\n  const x = (v) => 68 + (Number(v) - lo) / Math.max(hi - lo, 0.01) * 664;\\n  return <section className=\\"vi-price-summary\\" aria-label=\\"现价与三层价值对比\\" style={{ marginBottom: 16, color: '#172b46' }}>\\n    <style>{`.vi-price-summary .vi-price-grid{display:grid;grid-template-columns:1.05fr 1fr 1.14fr 1fr;gap:12px}.vi-price-summary .vi-price-card{border-radius:12px;padding:18px 16px;min-width:0}.vi-price-summary .vi-price-number{font-size:30px;font-weight:700;line-height:1.35;letter-spacing:-.8px;font-variant-numeric:tabular-nums}.vi-price-summary .vi-price-unit{font-size:12px;font-weight:400;letter-spacing:0;margin-left:5px;white-space:nowrap}.vi-price-summary .vi-price-caption{font-size:12px;margin-top:9px;line-height:1.5}.vi-price-summary .vi-price-verdict{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin:16px 0 4px}.vi-price-summary .vi-price-scale{width:100%;display:block;height:auto}@media(max-width:1100px){.vi-price-summary .vi-price-grid{grid-template-columns:1fr 1fr}.vi-price-summary .vi-price-number{font-size:28px}.vi-price-summary .vi-price-scale{min-width:560px}}`}</style>\\n    <div className=\\"vi-price-grid\\">\\n      <div className=\\"vi-price-card\\" style={{ background: '#152b46', color: '#fff', border: '1px solid #152b46' }}>\\n        <div style={{ fontSize: 13, color: '#c4d3e4', marginBottom: 10 }}>● 当前市场价</div>\\n        <div className=\\"vi-price-number\\">{fmtPrice(price)}<span className=\\"vi-price-unit\\">{unit} / 股</span></div>\\n        <div className=\\"vi-price-caption\\" style={{ color: '#c4d3e4' }}>市场报价 · {date || '日期未知'}</div>\\n      </div>\\n      {ordered.map((s) => {\\n        const p = palettes[s.name] || palettes['盈利能力价值'];\\n        const primary = !!s.isBase;\\n        return <div key={s.name} className=\\"vi-price-card\\" style={{ background: p.bg, border: `${primary ? 2 : 1}px solid ${p.border}`, color: p.ink }}>\\n          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 6, fontSize: 13, marginBottom: 10 }}>\\n            <span>{p.icon} {s.name}</span><span style={{ fontSize: 10, background: primary ? p.ink : 'transparent', color: primary ? '#fff' : p.ink, padding: '2px 6px', borderRadius: 4 }}>{primary ? '主估值层' : p.hint}</span>\\n          </div>\\n          <div className=\\"vi-price-number\\" style={{ fontSize: primary ? 34 : undefined }}>{fmtPrice(s.value)}<span className=\\"vi-price-unit\\">{unit} / 股</span></div>\\n        </div>;\\n      })}\\n    </div>\\n    <div className=\\"vi-price-verdict\\">\\n      <strong style={{ fontSize: 18, color: '#1d4ed8' }}>{gap === null ? '现价与主估值层暂无法比较' : `现价比${base.name}${gap <= 0 ? '低' : '高'} ${(Math.abs(gap) * 100).toFixed(1)}%`}</strong>\\n      <span style={{ color: '#6b7788', fontSize: 12 }}>三层从保守到乐观：资产值多少、不增长值多少、算上增长值多少</span>\\n    </div>\\n    {points.length > 1 && valid(price) ? <div style={{ overflowX: 'auto' }}><svg className=\\"vi-price-scale\\" viewBox=\\"0 0 800 112\\" role=\\"img\\" aria-label={`价格位置，现价 ${fmtPrice(price)}，${points.map((s) => s.name + '估值 ' + fmtPrice(s.value)).join('，')}，单位${unit}`}>\\n      <line x1=\\"52\\" x2=\\"748\\" y1=\\"52\\" y2=\\"52\\" stroke=\\"#e7edf5\\" strokeWidth=\\"8\\" strokeLinecap=\\"round\\" />\\n      <line x1={x(Math.min(...points.map((s) => Number(s.value))))} x2={x(Math.max(...points.map((s) => Number(s.value))))} y1=\\"52\\" y2=\\"52\\" stroke=\\"#c9d8f4\\" strokeWidth=\\"8\\" strokeLinecap=\\"round\\" />\\n      {points.map((s, i) => <g key={s.name}><circle cx={x(s.value)} cy=\\"52\\" r={s.isBase ? 7 : 5} fill={(palettes[s.name] || palettes['盈利能力价值']).ink} stroke=\\"white\\" strokeWidth=\\"2\\" /><text x={x(s.value)} y={i % 2 ? 98 : 81} textAnchor=\\"middle\\" fontSize=\\"12\\" fill={(palettes[s.name] || palettes['盈利能力价值']).ink}>{s.name} {fmtPrice(s.value)}</text></g>)}\\n      <line x1={x(price)} x2={x(price)} y1=\\"29\\" y2=\\"59\\" stroke=\\"#152b46\\" strokeWidth=\\"2\\" strokeDasharray=\\"3 3\\" />\\n      <path d={`M ${x(price)-5} 23 L ${x(price)+5} 23 L ${x(price)} 30 Z`} fill=\\"#152b46\\" />\\n      <text x={x(price)} y=\\"16\\" textAnchor=\\"middle\\" fontWeight=\\"700\\" fontSize=\\"12\\" fill=\\"#152b46\\">现价 {fmtPrice(price)}</text>\\n    </svg></div> : null}\\n  </section>;\\n}\\n\\nconst CONFIG = {\\"code\\": \\"01810.HK\\", \\"links\\": [{\\"title\\": \\"⑤ 股权价值\\", \\"href\\": \\"/admin/ni22x9i8edw\\"}, {\\"title\\": \\"② 盈利能力\\", \\"href\\": \\"/admin/x5ctxkmoiur\\"}, {\\"title\\": \\"核心论点\\", \\"href\\": \\"/admin/9qrhfm3nwjl\\"}], \\"focus\\": \\"经营重点：手机与生态利润、汽车交付，以及 AI 等新业务的估值假设\\"};\\n// 驾驶舱关键读数（五家公司同一份）：现价与三层价值（主估值层）、隐含回报、质量自检。只读 vi_gw_value / vi_check。\\nconst { Alert, Button, Col, Row, Space, Statistic, Table, Tag, Typography } = ctx.libs.antd;\\nconst finite = (v) => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));\\nconst number = (v, digits = 2) => finite(v) ? Number(v).toFixed(digits) : '—';\\nconst percent = (v, digits = 1) => finite(v) ? `${(Number(v) * 100).toFixed(digits)}%` : '—';\\n\\nasync function listRows(collectionName, filter) {\\n  const resource = ctx.makeResource('MultiRecordResource');\\n  resource.setResourceName(collectionName);\\n  resource.setPageSize(200);\\n  if (filter) resource.setFilter(filter);\\n  await resource.refresh();\\n  return resource.getData() || [];\\n}\\n\\ntry {\\n  const [company] = await listRows('vi_company', { code: { $eq: CONFIG.code } });\\n  if (!company) throw new Error('未找到公司记录');\\n  const byCo = { company_id: { $eq: company.id } };\\n  const [values, checks] = await Promise.all([listRows('vi_gw_value', byCo), listRows('vi_check', byCo)]);\\n  const v = values[0];\\n  if (!v) throw new Error('这家公司还没有三层估值（预测与估值 / ② 盈利能力）');\\n  const layer = v.value_layer;\\n  const count = (result) => checks.filter((r) => r.result === result).length;\\n  const quote = finite(company.latest_fx) ? `（${number(company.latest_price_raw)} 港元 × ${number(company.latest_fx, 4)}）` : '';\\n  const layers = [['资产价值', v.av_ps, null], ['盈利能力价值', v.epv_ps, v.irr_epv], ['含增长价值', v.full_ps, v.irr_full]];\\n  const rows = layers.map(([name, value, irr]) => ({ name, value, irr }));\\n  const columns = [\\n    { title: '层', dataIndex: 'name', render: (x) => (x === layer ? <Typography.Text strong>{x}（主估值层）</Typography.Text> : x) },\\n    { title: '每股价值（元，今天）', dataIndex: 'value', align: 'right', render: (x) => number(x) },\\n    { title: '现价相对', key: 'gap', align: 'right', render: (_, r) => (finite(r.value) && Number(r.value) ? percent(company.latest_price / r.value - 1) : '—') },\\n    { title: '隐含年化回报（现价买入）', dataIndex: 'irr', align: 'right',\\n      render: (x) => (finite(x) ? <Typography.Text type={x >= v.hurdle ? 'success' : 'danger'}>{percent(x)}</Typography.Text> : '—') },\\n  ];\\n  ctx.render(\\n    <div>\\n      <Space wrap align=\\"center\\" style={{ justifyContent: 'space-between', width: '100%', marginBottom: 8 }}>\\n        <Typography.Title level={4} style={{ margin: 0 }}>{company.name} · 投资驾驶舱</Typography.Title>\\n        <Space wrap>{CONFIG.links.map((l) => <Button key={l.href} size=\\"small\\" href={l.href}>{l.title}</Button>)}</Space>\\n      </Space>\\n      <Typography.Paragraph type=\\"secondary\\" style={{ marginBottom: 16 }}>\\n        {company.code} · 股价 {company.latest_price_date || '—'} · 估值截至日 {v.as_of || '—'} · 股本 {number(v.shares, 2)} 亿股 · 主估值层 {layer || '未选'} · 门槛 {percent(v.hurdle)}\\n      </Typography.Paragraph>\\n      <PriceSummary price={company.latest_price} date={company.latest_price_date} unit=\\"元\\"\\n        scenarios={rows.map((r) => ({ name: r.name, value: r.value, isBase: r.name === layer }))} />\\n      <Row gutter={[20, 16]}>\\n        <Col xs={12} lg={6}><Statistic title={`现价（记账币种）${quote}`} value={number(company.latest_price)} suffix=\\"元\\" /></Col>\\n        <Col xs={12} lg={6}><Statistic title={layer || '主估值层'} value={number(v.value_ps)} suffix=\\"元\\" /></Col>\\n        <Col xs={12} lg={6}><Statistic title=\\"主估值层的隐含年化回报\\" value={finite(v.implied_irr) ? (v.implied_irr * 100).toFixed(1) : '—'} suffix=\\"%\\" /></Col>\\n        <Col xs={12} lg={6}><Statistic title=\\"资产负债桥（每股，截至日）\\" value={number(v.bridge / v.shares)} suffix=\\"元\\" /></Col>\\n      </Row>\\n      <Typography.Paragraph style={{ margin: '16px 0 12px' }}>{v.conclusion}</Typography.Paragraph>\\n      <Table size=\\"small\\" rowKey=\\"name\\" pagination={false} dataSource={rows} columns={columns} scroll={{ x: 640 }}\\n        style={{ fontVariantNumeric: 'tabular-nums' }} />\\n      <Typography.Paragraph type=\\"secondary\\" style={{ margin: '10px 0' }}>\\n        三层价值都已加上资产负债桥、按门槛滚到今天；三层本身就是从保守到乐观的三种情形，结论看主估值层。{CONFIG.focus ? `${CONFIG.focus}。` : ''}\\n      </Typography.Paragraph>\\n      <Space wrap>\\n        <Typography.Text type=\\"secondary\\">质量自检</Typography.Text>\\n        <Tag color=\\"green\\">通过 {count('通过')}</Tag><Tag color=\\"gold\\">提示 {count('提示')}</Tag>\\n        <Tag color={count('阻断') ? 'red' : 'default'}>阻断 {count('阻断')}</Tag>\\n        <Typography.Text type=\\"secondary\\">PE TTM {number(company.pe_ttm)} · PB {number(company.pb)}（{company.pe_pb_date || '—'}，市场口径）</Typography.Text>\\n      </Space>\\n    </div>,\\n  );\\n} catch (error) {\\n  const msg = String(error?.message || error);\\n  ctx.render(msg.startsWith('这家公司还没有')\\n    ? <Alert type=\\"info\\" showIcon message=\\"还没有三层估值\\" description=\\"先在「预测与估值 / ② 盈利能力」填调整后利润表（样板见腾讯音乐）；下面的经营图表照常可看。\\" />\\n    : <Alert type=\\"error\\" showIcon message=\\"驾驶舱读取失败\\" description={msg} />);\\n}\\n"}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.kpi"}}}
