x60kc31vt0d	x60kc31vt0d	{"parentId":"97pgr505uly","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_risk"}},"__flowSurfaceMeta":{"declaredKey":"明细（编辑）.main"},"cardSettings":{"titleDescription":{"description":"① 功能定位：可能让这笔投资亏钱的事件。\\n② 数据库基本表：vi_risk_base（页面上新增、修改都写回这里）\\n③ 这张表格引用了哪些表格：\\n　「会削弱的论点」列 → 商业模式 / 核心论点\\n　「估值对应的假设依据」列 → 预测与估值 / 假设依据\\n　「预警指标」列 → 经营与财务 / 定量指标\\n　「依据事实」列 → 经营与财务 / 定性事实 / 全部事实\\n　「相关论点裁决」列（自动）← 商业模式 / 核心论点\\n④ 哪些表格引用了这张表格：\\n　预测与估值 / ⑤ 股权价值 的「用到的宏观数据」列（自动）\\n　经营与财务 / 定量指标 的「重点跟踪」列（自动）\\n　经营与财务 / 定量指标 的「使用公司」列（自动）"}},"tableSettings":{"pageSize":{"pageSize":50},"tableDensity":{"size":"middle"},"defaultSorting":{"sort":[{"field":"code","direction":"asc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"company_id","operator":"$eq","value":7}]}}}}}
