urg8p1c8jda	urg8p1c8jda	{"parentId":"ve827t5z30v","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_thesis"}},"__flowSurfaceMeta":{"declaredKey":"明细（编辑）.main"},"cardSettings":{"titleDescription":{"description":"① 功能定位：决定公司价值的关键判断（问题与结论），每条正反辩论后下结论。\\n② 数据库基本表：vi_thesis_base（页面上新增、修改都写回这里）\\n③ 这张表格引用了哪些表格：\\n　「依据事实」列 → 经营与财务 / 定性事实 / 全部事实\\n　「依据指标」列 → 经营与财务 / 定量指标\\n　「最近年度」「最近值」「自动检查结果」列（自动）← 定量指标按年汇总（财务模型里的历史年度）\\n　「假设依据（状态）」列（自动）← 预测与估值 / 假设依据\\n④ 哪些表格引用了这张表格：\\n　商业模式 / 竞争壁垒 的「相关论点」列\\n　商业模式 / 风险分析 的「会削弱的论点」列\\n　商业模式 / 价投适配度 的「相关论点」列\\n　预测与估值 / 假设依据 的「相关论点」列\\n　商业模式 / 竞争壁垒 的「已辩论的论点数」「论点裁决」列（自动）\\n　商业模式 / 风险分析 的「相关论点裁决」列（自动）"}},"tableSettings":{"pageSize":{"pageSize":50},"defaultSorting":{"sort":[{"field":"id","direction":"asc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"company_id","operator":"$eq","value":7}]}}}}}
