n1pgbq8k1vr	n1pgbq8k1vr	{"parentId":"3ev3v88ud04","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_moat"}},"__flowSurfaceMeta":{"declaredKey":"明细（编辑）.main"},"cardSettings":{"titleDescription":{"description":"① 功能定位：公司有哪些护城河，各靠什么机制成立。\\n② 数据库基本表：vi_moat_base（页面上新增、修改都写回这里）\\n③ 这张表格引用了哪些表格：\\n　「依据事实」列 → 经营与财务 / 定性事实 / 全部事实\\n　「依据指标」列 → 经营与财务 / 定量指标\\n　「相关论点」列 → 商业模式 / 核心论点\\n　「最近年度」「最近值」「自动检查结果」列（自动）← 定量指标按年汇总（财务模型里的历史年度）\\n　「已辩论的论点数」「论点裁决」列（自动）← 商业模式 / 核心论点\\n④ 哪些表格引用了这张表格：无"}},"tableSettings":{"pageSize":{"pageSize":50},"defaultSorting":{"sort":[{"field":"id","direction":"asc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"company_id","operator":"$eq","value":2}]}}}}}
