2936	2026-11-11 23:28:47.554+08	2026-11-11 23:28:47.554+08	19j2ismksn9	\N	SELECT h.year, round(h.volume::numeric, CASE WHEN h.volume < 100 THEN 3 ELSE 0 END) AS "业务量" FROM vi_fin_history h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '002078.SZ' WHERE h.volume IS NOT NULL ORDER BY h.year
2937	2026-11-11 23:28:47.625+08	2026-11-11 23:28:47.625+08	gilw3ka70hc	\N	SELECT x.period, x.k AS "口径", round(x.v::numeric, 2) AS "毛利率（%）" FROM (SELECT s.period, s.obs_date, '太阳纸业' AS k, s.value AS v FROM vi_series s JOIN vi_metric_base m ON m.id = s.metric_id AND m.name = '毛利率' AND m.company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ') WHERE s.basis = '单季' UNION ALL SELECT l.period, l.obs_date, '七家同业中位数', g.value - l.value FROM vi_series l JOIN vi_metric_base lm ON lm.id = l.metric_id AND lm.name = '毛利率领先同业中位数' JOIN vi_metric_base gm ON gm.company_id = lm.company_id AND gm.name = '毛利率' JOIN vi_series g ON g.metric_id = gm.id AND g.period = l.period AND g.basis = '单季' WHERE l.basis = '单季' AND lm.company_id = (SELECT id FROM vi_company_base WHERE code = '002078.SZ')) x WHERE x.obs_date >= vi_today() - interval '3 years' ORDER BY x.obs_date, 2
2938	2026-11-11 23:28:47.667+08	2026-11-11 23:28:47.667+08	q9z97beoc2p	\N	SELECT o.obs_date, CASE mt.code WHEN 'SP.SHFE.SINA' THEN '纸浆期货' WHEN 'OP.SHFE.SINA' THEN '胶版纸期货' ELSE '纸浆现货' END AS "口径", o.value AS "价格" FROM vi_obs_current o JOIN vi_metric_base mt ON mt.id = o.metric_id WHERE mt.code IN ('SP.SHFE.SINA', 'OP.SHFE.SINA', 'SP.SPOT.100PPI') AND o.obs_date >= current_date - 730 ORDER BY o.obs_date, 2
