396008643690496	2026-11-05 13:13:56.627+08	2026-11-05 13:13:58.816+08	g87ymly4mep	⑤ 校验去重并入库 · 仅本次记录	396008639496192	\N	396008647884800	sql	{"dataSource":"main","sql":"-- 仅处理④保存的这一条原始记录，按数据源加锁，避免同源任务并发入库。\\nSELECT pg_advisory_xact_lock(91005, CAST(:collector_id AS integer));\\nWITH c AS MATERIALIZED (\\n  SELECT r.id, k.metric_id, r.collected_at,\\n         x.parsed_date, x.parsed_value, x.decision\\n  FROM vi_raw_capture_base r\\n  JOIN vi_raw_capture_calc x ON x.id = r.id\\n  JOIN vi_collector_base k ON k.id = r.collector_id\\n  WHERE r.id = :raw_id AND r.collector_id = :collector_id AND r.status = '待入库'\\n  FOR UPDATE OF r\\n), ins AS (\\n  INSERT INTO vi_observation_base (metric_id, obs_date, value, collected_at, raw_capture_id)\\n  SELECT metric_id, parsed_date, parsed_value, collected_at, id\\n  FROM c WHERE decision = '可入库'\\n  RETURNING raw_capture_id\\n)\\nUPDATE vi_raw_capture_base r\\nSET status = CASE\\n  WHEN c.decision = '可入库' AND EXISTS (SELECT 1 FROM ins WHERE raw_capture_id = c.id) THEN '已入库'\\n  WHEN c.decision = '抓取失败' THEN '抓取失败'\\n  WHEN c.decision LIKE '重复%' THEN '重复未入库'\\n  ELSE '校验失败' END\\nFROM c WHERE r.id = c.id\\nRETURNING r.id AS raw_id, r.status;\\n","withMeta":false,"variables":[{"name":"raw_id","value":"{{$jobsMapByNodeKey.450sh92aa84.id}}"},{"name":"collector_id","value":4}]}	396008620621824
