black',\\r\\n            lineColor : 'black',\\r\\n        } ],\\r\\n\\r\\n        legend : {\\r\\n            enabled : true,\\r\\n            align: 'left',\\r\\n            layout: 'vertical',\\r\\n            floating: true,\\r\\n            itemMarginTop: 3,\\r\\n            x: 45,\\r\\n            y: 10,\\r\\n            itemStyle: {\\r\\n                fontWeight:\\"normal\\",\\r\\n                fontSize: \\"12px\\",\\r\\n                fontFamily: \\"宋体\\",\\r\\n                color: \\"#333333\\",\\r\\n                cursor: \\"default\\",\\r\\n            },\\r\\n        },\\r\\n        credits : {\\r\\n            enabled : false //去掉higcharts.com\\r\\n        },\\r\\n        tooltip : {\\r\\n            shared : false,\\r\\n            split : true,\\r\\n            animation : false,\\r\\n            shape : 'square',\\r\\n            crosshairs : {\\r\\n                width : 1,\\r\\n                color : 'red'\\r\\n            },\\r\\n            distance : 3,//距离某个点的距离\\r\\n            useHTML : true,\\r\\n            borderWidth : 1,\\r\\n            headerFormat : '<small style=\\"background-color:#DC143C\\">{point.key}</small><table border=\\"5\\">',\\r\\n            pointFormat : '<tr><td style=\\"text-align: right,color:{point.color}\\">{point.y:.4f}%</td></tr>',\\r\\n            footerFormat : '</table>',\\r\\n        },\\r\\n        plotOptions : {\\r\\n            series: {\\r\\n                animation:false,\\r\\n                states:{\\r\\n                    hover:{\\r\\n                        lineWidthPlus: 0\\r\\n                    },\\r\\n                },\\r\\n                marker:{\\r\\n                    symbol:'circle',\\r\\n                    enabled:true,\\r\\n                    radius:0.1\\r\\n                },\\r\\n                connectNulls:true,//连接空点\\r\\n            },\\r\\n        },\\r\\n        series : []\\r\\n    }\\r\\n    function query(){\\r\\n        queryGjqxInfo();\\r\\n\\r\\n        var wo